window.MENTOR_DATA={"concepts":[{"id":"estadistica-01","domain":"estadistica","term":"Escala nominal","topic":"Variables","definition":"Clasifica categorías sin orden intrínseco.","scenario":"Una base registra el tipo de dependencia: regional, provincial o central.","application":"Usa frecuencias y proporciones; no interpretes promedios de códigos de categoría.","pitfall":"Codificar categorías con números no las convierte en cuantitativas.","difficulty":"Básica","sourceIds":[]},{"id":"estadistica-02","domain":"estadistica","term":"Escala ordinal","topic":"Variables","definition":"Clasifica categorías con un orden, pero sin garantizar distancias iguales.","scenario":"Una encuesta usa niveles bajo, medio y alto de satisfacción.","application":"Analiza orden, medianas o rangos cuando corresponda; evita asumir distancia constante.","pitfall":"Tratar 1, 2 y 3 como si fueran intervalos exactos puede inducir conclusiones falsas.","difficulty":"Básica","sourceIds":[]},{"id":"estadistica-03","domain":"estadistica","term":"Mediana","topic":"Descriptiva","definition":"Valor central al ordenar observaciones; es robusta frente a valores extremos.","scenario":"Los tiempos de trámite tienen unos pocos casos extremadamente largos.","application":"Resume el centro con mediana y acompaña con percentiles o rango intercuartílico.","pitfall":"Usar solo la media puede ocultar la experiencia típica cuando hay asimetría.","difficulty":"Básica","sourceIds":[]},{"id":"estadistica-04","domain":"estadistica","term":"Desviación estándar","topic":"Descriptiva","definition":"Mide la dispersión de los valores alrededor de la media en las mismas unidades de la variable.","scenario":"Dos dependencias tienen igual promedio de días, pero una es mucho más variable.","application":"Compara variabilidad y estabilidad del proceso, idealmente junto con distribución y outliers.","pitfall":"Una desviación menor no prueba por sí sola mejor calidad del servicio.","difficulty":"Media","sourceIds":[]},{"id":"estadistica-05","domain":"estadistica","term":"Percentil","topic":"Descriptiva","definition":"Indica el valor por debajo del cual cae un porcentaje dado de observaciones.","scenario":"Se quiere conocer el tiempo que no supera el 90 % de los trámites.","application":"Usa P90 para describir colas de tiempos y niveles de servicio.","pitfall":"Confundir percentil 90 con 90 % del valor máximo.","difficulty":"Media","sourceIds":[]},{"id":"estadistica-06","domain":"estadistica","term":"Probabilidad condicional","topic":"Probabilidad","definition":"Probabilidad de un evento dado que ya ocurrió otro evento.","scenario":"Se analiza la probabilidad de error dado que el registro proviene de una fuente específica.","application":"Compara riesgos condicionados y evita mezclar poblaciones con composiciones distintas.","pitfall":"P(A|B) no es necesariamente igual a P(B|A).","difficulty":"Media","sourceIds":[]},{"id":"estadistica-07","domain":"estadistica","term":"Sesgo de selección","topic":"Muestreo","definition":"Distorsión producida cuando la muestra no representa adecuadamente la población objetivo.","scenario":"Un diagnóstico usa solo entidades que voluntariamente entregaron datos temprano.","application":"Evalúa cobertura, mecanismo de selección y diferencias entre incluidos y no incluidos.","pitfall":"Un tamaño de muestra grande no corrige automáticamente un sesgo sistemático.","difficulty":"Alta","sourceIds":[]},{"id":"estadistica-08","domain":"estadistica","term":"Intervalo de confianza","topic":"Inferencia","definition":"Rango construido por un procedimiento estadístico para expresar incertidumbre sobre una estimación.","scenario":"Se estima el tiempo promedio de respuesta a partir de una muestra.","application":"Reporta estimación junto con su incertidumbre y supuestos del muestreo.","pitfall":"No significa que, tras calcularlo, haya una probabilidad fija de que el parámetro esté dentro.","difficulty":"Media","sourceIds":[]},{"id":"estadistica-09","domain":"estadistica","term":"Hipótesis nula","topic":"Inferencia","definition":"Proposición de referencia que una prueba estadística contrasta con los datos.","scenario":"Se compara si dos dependencias tienen el mismo tiempo promedio.","application":"Define H0 y H1 antes de interpretar el resultado y el nivel de significancia.","pitfall":"No rechazar H0 no equivale a demostrar que H0 es verdadera.","difficulty":"Media","sourceIds":[]},{"id":"estadistica-10","domain":"estadistica","term":"p-value","topic":"Inferencia","definition":"Probabilidad, bajo H0 y el modelo asumido, de observar un resultado al menos tan extremo como el obtenido.","scenario":"Una prueba produce p=0,03 con alfa=0,05.","application":"Interpreta incompatibilidad con H0 según el criterio fijado, junto con tamaño de efecto e incertidumbre.","pitfall":"No es la probabilidad de que H0 sea verdadera.","difficulty":"Alta","sourceIds":[]},{"id":"estadistica-11","domain":"estadistica","term":"Error tipo I","topic":"Inferencia","definition":"Rechazar H0 cuando H0 es verdadera.","scenario":"Un análisis declara diferencia donde en realidad no existe.","application":"Controla el riesgo con el nivel de significancia y considera multiplicidad de pruebas.","pitfall":"Reducir alfa puede aumentar otros costos, como el error tipo II.","difficulty":"Media","sourceIds":[]},{"id":"estadistica-12","domain":"estadistica","term":"Tamaño del efecto","topic":"Inferencia","definition":"Cuantifica la magnitud práctica de una diferencia o relación.","scenario":"Una diferencia es estadísticamente significativa pero solo reduce 0,2 días de trámite.","application":"Evalúa relevancia práctica además de significancia estadística.","pitfall":"Un p-value pequeño no garantiza un efecto importante.","difficulty":"Alta","sourceIds":[]},{"id":"estadistica-13","domain":"estadistica","term":"Correlación","topic":"Relaciones","definition":"Resume la intensidad y dirección de una asociación entre variables bajo una medida específica.","scenario":"A mayor carga de trabajo, también aumenta el tiempo de respuesta.","application":"Usa correlación como evidencia de asociación y complementa con diseño y contexto para causalidad.","pitfall":"Correlación no demuestra causalidad.","difficulty":"Básica","sourceIds":[]},{"id":"estadistica-14","domain":"estadistica","term":"Regresión","topic":"Modelado","definition":"Modela una variable objetivo en función de una o más variables explicativas.","scenario":"Se quiere estimar tiempo de respuesta usando carga, región y tipo de caso.","application":"Revisa especificación, residuos, validación y capacidad de generalización.","pitfall":"R² alto no garantiza causalidad ni ausencia de sesgos.","difficulty":"Media","sourceIds":[]},{"id":"estadistica-15","domain":"estadistica","term":"Datos faltantes","topic":"Calidad estadística","definition":"Ausencia de valores cuya causa puede afectar estimaciones y modelos.","scenario":"Una variable sensible aparece vacía con mayor frecuencia en un grupo específico.","application":"Caracteriza el patrón de faltantes antes de eliminar o imputar y documenta la decisión.","pitfall":"Imputar sin estudiar el mecanismo puede introducir sesgo.","difficulty":"Alta","sourceIds":[]},{"id":"ciencia-datos-01","domain":"ciencia-datos","term":"Aprendizaje supervisado","topic":"Paradigmas","definition":"Aprende una relación usando ejemplos con variable objetivo conocida.","scenario":"Existe un histórico etiquetado de casos prioritarios y no prioritarios.","application":"Separa entrenamiento y evaluación y define una métrica alineada con el costo del error.","pitfall":"Usar etiquetas de mala calidad transmite ese problema al modelo.","difficulty":"Básica","sourceIds":["sklearn"]},{"id":"ciencia-datos-02","domain":"ciencia-datos","term":"Clasificación","topic":"Modelos","definition":"Predice una categoría o clase.","scenario":"Se quiere predecir si un caso requiere revisión prioritaria.","application":"Define clases, costo de falsos positivos/negativos y métricas apropiadas.","pitfall":"Accuracy puede ser engañosa con clases desbalanceadas.","difficulty":"Básica","sourceIds":["sklearn"]},{"id":"ciencia-datos-03","domain":"ciencia-datos","term":"Regresión predictiva","topic":"Modelos","definition":"Predice un valor numérico continuo.","scenario":"Se estima cuántos días tardará un trámite.","application":"Evalúa MAE/RMSE y analiza errores por segmentos relevantes.","pitfall":"Un buen promedio de error puede esconder fallas graves en subgrupos.","difficulty":"Básica","sourceIds":["sklearn"]},{"id":"ciencia-datos-04","domain":"ciencia-datos","term":"Clustering","topic":"Modelos","definition":"Agrupa observaciones por similitud sin usar etiquetas objetivo.","scenario":"Se buscan perfiles de comportamiento en registros sin categorías previas.","application":"Escala variables, valida estabilidad e interpreta grupos con contexto.","pitfall":"Un cluster no es automáticamente una categoría real o causal.","difficulty":"Media","sourceIds":["sklearn"]},{"id":"ciencia-datos-05","domain":"ciencia-datos","term":"Conjunto de prueba","topic":"Validación","definition":"Datos reservados para estimar desempeño sobre casos no usados en el ajuste.","scenario":"Se desarrolla un modelo con histórico 2024-2025 y se reserva una parte para prueba.","application":"Mantén el test aislado de decisiones de entrenamiento y preprocesamiento aprendido.","pitfall":"Reutilizar el test repetidamente termina sobreajustando decisiones al test.","difficulty":"Media","sourceIds":["sklearn"]},{"id":"ciencia-datos-06","domain":"ciencia-datos","term":"Validación cruzada","topic":"Validación","definition":"Evalúa el modelo sobre múltiples particiones para estimar estabilidad.","scenario":"Hay pocos datos y se desea comparar modelos de manera más robusta.","application":"Usa particiones apropiadas al problema y evita fuga entre folds.","pitfall":"En series temporales no debe mezclarse futuro con pasado arbitrariamente.","difficulty":"Media","sourceIds":["sklearn"]},{"id":"ciencia-datos-07","domain":"ciencia-datos","term":"Overfitting","topic":"Generalización","definition":"El modelo aprende demasiado el entrenamiento y pierde capacidad de generalizar.","scenario":"Un modelo logra 99 % en entrenamiento y 72 % en validación.","application":"Simplifica, regulariza, mejora datos o aumenta validación según el caso.","pitfall":"Más complejidad no implica mejor desempeño real.","difficulty":"Media","sourceIds":["sklearn"]},{"id":"ciencia-datos-08","domain":"ciencia-datos","term":"Underfitting","topic":"Generalización","definition":"El modelo es demasiado simple o insuficientemente entrenado para capturar la señal.","scenario":"El desempeño es bajo tanto en entrenamiento como en validación.","application":"Mejora representación, modelo o entrenamiento antes de culpar a la validación.","pitfall":"Agregar regularización a un modelo ya subajustado puede empeorarlo.","difficulty":"Media","sourceIds":["sklearn"]},{"id":"ciencia-datos-09","domain":"ciencia-datos","term":"Data leakage","topic":"Calidad ML","definition":"Información no disponible al momento real de predicción contamina entrenamiento o evaluación.","scenario":"Una variable contiene el resultado final del proceso que se quiere predecir.","application":"Define el punto temporal de predicción y construye features solo con información disponible entonces.","pitfall":"La fuga puede producir métricas espectacularmente altas pero inútiles en producción.","difficulty":"Alta","sourceIds":["sklearn"]},{"id":"ciencia-datos-10","domain":"ciencia-datos","term":"Precision","topic":"Métricas","definition":"Proporción de predicciones positivas que realmente son positivas.","scenario":"Una alerta genera costos altos cuando acusa falsamente un caso.","application":"Prioriza precision cuando falsos positivos son particularmente costosos.","pitfall":"Alta precision puede coexistir con bajo recall.","difficulty":"Media","sourceIds":["sklearn"]},{"id":"ciencia-datos-11","domain":"ciencia-datos","term":"Recall","topic":"Métricas","definition":"Proporción de positivos reales que el modelo logra detectar.","scenario":"Omitir un caso crítico tiene alto costo institucional.","application":"Prioriza recall cuando perder positivos es más grave que revisar falsos positivos.","pitfall":"Al maximizar recall sin control puede crecer mucho el número de falsos positivos.","difficulty":"Media","sourceIds":["sklearn"]},{"id":"ciencia-datos-12","domain":"ciencia-datos","term":"F1-score","topic":"Métricas","definition":"Media armónica de precision y recall.","scenario":"Se necesita balancear detección y exactitud de alertas en clases desbalanceadas.","application":"Úsalo cuando ambas dimensiones importan y complementa con métricas por clase.","pitfall":"F1 ignora verdaderos negativos y no siempre refleja costos reales.","difficulty":"Media","sourceIds":["sklearn"]},{"id":"ciencia-datos-13","domain":"ciencia-datos","term":"ROC-AUC","topic":"Métricas","definition":"Mide capacidad de ranking entre clases a través de distintos umbrales.","scenario":"Se comparan clasificadores antes de fijar el umbral operativo.","application":"Úsala como medida global de separación y revisa también métricas en el umbral real.","pitfall":"Puede verse optimista en problemas muy desbalanceados; PR-AUC puede aportar más.","difficulty":"Alta","sourceIds":["sklearn"]},{"id":"ciencia-datos-14","domain":"ciencia-datos","term":"Feature engineering","topic":"Representación","definition":"Transforma o crea variables para representar mejor el fenómeno.","scenario":"Fechas crudas se transforman en antigüedad, día de semana o tiempo transcurrido.","application":"Diseña features con conocimiento del proceso y documenta transformaciones.","pitfall":"Crear variables con información futura genera leakage.","difficulty":"Media","sourceIds":["sklearn"]},{"id":"ciencia-datos-15","domain":"ciencia-datos","term":"Drift","topic":"Producción","definition":"Cambio en distribución de datos o relación con el objetivo después del despliegue.","scenario":"El comportamiento de casos de 2027 difiere del histórico usado para entrenar.","application":"Monitorea datos y desempeño, define umbrales y estrategia de reentrenamiento.","pitfall":"Un modelo no permanece válido indefinidamente solo porque funcionó al inicio.","difficulty":"Alta","sourceIds":["sklearn"]},{"id":"ingenieria-datos-01","domain":"ingenieria-datos","term":"ETL","topic":"Integración","definition":"Extraer, transformar y luego cargar datos al destino.","scenario":"Tres sistemas entregan formatos heterogéneos que deben estandarizarse antes de cargar al warehouse.","application":"Controla esquema, calidad, errores y trazabilidad en cada etapa.","pitfall":"Transformaciones opacas dificultan auditoría y mantenimiento.","difficulty":"Básica","sourceIds":[]},{"id":"ingenieria-datos-02","domain":"ingenieria-datos","term":"ELT","topic":"Integración","definition":"Extraer y cargar datos primero, transformándolos en el motor de destino.","scenario":"Un almacén analítico escalable recibe datos crudos y ejecuta transformaciones internas.","application":"Aprovecha potencia del destino y conserva capas crudas con gobernanza.","pitfall":"Cargar primero no elimina la necesidad de calidad, seguridad y costos controlados.","difficulty":"Media","sourceIds":[]},{"id":"ingenieria-datos-03","domain":"ingenieria-datos","term":"Pipeline de datos","topic":"Integración","definition":"Secuencia automatizada de tareas para mover, validar y transformar datos.","scenario":"Cada noche se consolidan registros de varias entidades y se recalculan indicadores.","application":"Diseña observabilidad, reintentos, dependencias y manejo de fallos.","pitfall":"Un pipeline sin monitoreo puede fallar silenciosamente.","difficulty":"Básica","sourceIds":[]},{"id":"ingenieria-datos-04","domain":"ingenieria-datos","term":"Idempotencia","topic":"Confiabilidad","definition":"Propiedad por la que repetir una operación produce el mismo estado esperado sin duplicar efectos.","scenario":"Un job se reintenta tras una caída durante la carga.","application":"Usa claves, upsert o checkpoints para que el reintento sea seguro.","pitfall":"Reintentar cargas no idempotentes puede duplicar registros.","difficulty":"Alta","sourceIds":[]},{"id":"ingenieria-datos-05","domain":"ingenieria-datos","term":"Procesamiento batch","topic":"Procesamiento","definition":"Procesa conjuntos acumulados en intervalos definidos.","scenario":"Un reporte institucional se actualiza cada madrugada.","application":"Úsalo cuando latencia de minutos/horas es aceptable y simplifica operación.","pitfall":"No es adecuado si la decisión requiere reacción casi inmediata.","difficulty":"Básica","sourceIds":[]},{"id":"ingenieria-datos-06","domain":"ingenieria-datos","term":"Procesamiento streaming","topic":"Procesamiento","definition":"Procesa eventos de forma continua o con baja latencia.","scenario":"Se requiere detectar anomalías pocos segundos después de recibir eventos.","application":"Diseña manejo de orden, duplicados, ventanas y tolerancia a fallos.","pitfall":"Streaming agrega complejidad y no debe usarse sin necesidad real.","difficulty":"Alta","sourceIds":[]},{"id":"ingenieria-datos-07","domain":"ingenieria-datos","term":"Data warehouse","topic":"Arquitectura","definition":"Repositorio estructurado optimizado para análisis consistente e histórico.","scenario":"La entidad consolida indicadores de múltiples sistemas con definiciones comunes.","application":"Modela dimensiones, hechos, calidad y gobierno de métricas.","pitfall":"Copiar datos sin modelo semántico no crea automáticamente un warehouse útil.","difficulty":"Media","sourceIds":[]},{"id":"ingenieria-datos-08","domain":"ingenieria-datos","term":"Data lake","topic":"Arquitectura","definition":"Repositorio de datos en diversos formatos y niveles de preparación.","scenario":"Se conservan archivos, eventos, imágenes y datos tabulares para usos analíticos futuros.","application":"Organiza zonas, catálogo, seguridad y ciclo de vida.","pitfall":"Sin gobierno puede convertirse en un data swamp.","difficulty":"Media","sourceIds":[]},{"id":"ingenieria-datos-09","domain":"ingenieria-datos","term":"Data mart","topic":"Arquitectura","definition":"Subconjunto orientado a un área o proceso específico.","scenario":"Una dirección necesita un modelo analítico especializado sobre trámites.","application":"Aísla necesidades de negocio manteniendo definiciones corporativas consistentes.","pitfall":"Crear marts desconectados puede multiplicar métricas contradictorias.","difficulty":"Media","sourceIds":[]},{"id":"ingenieria-datos-10","domain":"ingenieria-datos","term":"Modelo estrella","topic":"Modelado","definition":"Modelo dimensional con hechos centrales relacionados con dimensiones descriptivas.","scenario":"Se analizan trámites por fecha, dependencia, territorio y tipo.","application":"Define primero el grano y luego dimensiones y medidas.","pitfall":"Mezclar granos en una tabla de hechos genera dobles conteos.","difficulty":"Media","sourceIds":[]},{"id":"ingenieria-datos-11","domain":"ingenieria-datos","term":"Grano de hecho","topic":"Modelado","definition":"Nivel exacto que representa cada fila de una tabla de hechos.","scenario":"Cada fila representa un trámite por evento, no un trámite completo.","application":"Declara el grano antes de diseñar medidas y relaciones.","pitfall":"Un grano ambiguo hace que los indicadores sean inconsistentes.","difficulty":"Alta","sourceIds":[]},{"id":"ingenieria-datos-12","domain":"ingenieria-datos","term":"Slowly Changing Dimension","topic":"Modelado","definition":"Técnica para gestionar cambios históricos en atributos dimensionales.","scenario":"Una dependencia cambia de región o denominación y se necesita conservar historia.","application":"Elige estrategia según necesidad de conservar estado anterior o solo actual.","pitfall":"Sobrescribir siempre puede destruir contexto histórico necesario.","difficulty":"Alta","sourceIds":[]},{"id":"ingenieria-datos-13","domain":"ingenieria-datos","term":"Metadatos","topic":"Gobierno técnico","definition":"Datos que describen significado, estructura, origen, responsable y uso de otros datos.","scenario":"Un catálogo explica definición, tipo y dueño de cada campo.","application":"Mantén metadatos vinculados al ciclo de vida y cambios del dato.","pitfall":"Un diccionario desactualizado puede ser más dañino que no tenerlo.","difficulty":"Básica","sourceIds":[]},{"id":"ingenieria-datos-14","domain":"ingenieria-datos","term":"Linaje de datos","topic":"Gobierno técnico","definition":"Trazabilidad del origen y transformaciones de un dato hasta su consumo.","scenario":"Un indicador debe rastrearse desde dashboard hasta campos fuente.","application":"Registra fuentes, transformaciones, versiones y dependencias.","pitfall":"Sin linaje, investigar discrepancias consume mucho tiempo y reduce confianza.","difficulty":"Media","sourceIds":[]},{"id":"ingenieria-datos-15","domain":"ingenieria-datos","term":"Reglas de calidad","topic":"Calidad","definition":"Controles medibles sobre completitud, validez, consistencia, unicidad u oportunidad.","scenario":"Un registro exige identificación única, fecha válida y código territorial existente.","application":"Implementa reglas automáticas, umbrales y responsables de corrección.","pitfall":"Declarar que los datos son de calidad sin métricas no es suficiente.","difficulty":"Media","sourceIds":[]},{"id":"bases-sistemas-01","domain":"bases-sistemas","term":"Clave primaria","topic":"Modelo relacional","definition":"Atributo o conjunto que identifica de forma única cada fila.","scenario":"Una tabla de organizaciones necesita un identificador estable.","application":"Usa una PK única, no nula y estable para relacionar registros.","pitfall":"Elegir un atributo mutable como PK complica integridad y referencias.","difficulty":"Básica","sourceIds":["postgres"]},{"id":"bases-sistemas-02","domain":"bases-sistemas","term":"Clave foránea","topic":"Modelo relacional","definition":"Restricción que relaciona filas y protege integridad referencial.","scenario":"Un trámite referencia la dependencia responsable.","application":"Define FK y reglas de actualización/borrado coherentes con el negocio.","pitfall":"Guardar IDs sin constraint permite referencias huérfanas.","difficulty":"Básica","sourceIds":["postgres"]},{"id":"bases-sistemas-03","domain":"bases-sistemas","term":"Normalización","topic":"Modelo relacional","definition":"Organiza datos para reducir redundancia y anomalías según dependencias.","scenario":"Una tabla repite información de dependencia en miles de trámites.","application":"Separa entidades cuando mejora integridad y mantenimiento; desnormaliza solo con razón.","pitfall":"Normalizar mecánicamente sin considerar consultas y semántica puede complicar innecesariamente.","difficulty":"Media","sourceIds":["postgres"]},{"id":"bases-sistemas-04","domain":"bases-sistemas","term":"JOIN","topic":"SQL","definition":"Combina filas de relaciones usando condiciones de correspondencia.","scenario":"Se requiere mostrar trámites junto con nombre de dependencia.","application":"Elige INNER/LEFT según si deben conservarse filas sin coincidencia.","pitfall":"Un JOIN con cardinalidad desconocida puede multiplicar filas y métricas.","difficulty":"Básica","sourceIds":["postgres"]},{"id":"bases-sistemas-05","domain":"bases-sistemas","term":"GROUP BY y HAVING","topic":"SQL","definition":"Agrupa filas para calcular agregados; HAVING filtra grupos resultantes.","scenario":"Se cuentan casos por dependencia y se conservan solo las que superan un umbral.","application":"Usa WHERE antes del agrupamiento cuando el filtro aplica a filas y HAVING para agregados.","pitfall":"Confundir WHERE y HAVING produce consultas incorrectas o ineficientes.","difficulty":"Media","sourceIds":["postgres"]},{"id":"bases-sistemas-06","domain":"bases-sistemas","term":"CTE","topic":"SQL","definition":"Expresión común que nombra temporalmente un resultado para estructurar una consulta.","scenario":"Una consulta compleja calcula etapas de depuración y agregación.","application":"Úsala para legibilidad y descomposición lógica; verifica el plan de ejecución.","pitfall":"Una CTE no garantiza por sí sola mejor rendimiento.","difficulty":"Media","sourceIds":["postgres"]},{"id":"bases-sistemas-07","domain":"bases-sistemas","term":"Función de ventana","topic":"SQL","definition":"Calcula resultados sobre un conjunto relacionado sin colapsar filas como GROUP BY.","scenario":"Se necesita ranking por dependencia manteniendo cada registro.","application":"Usa PARTITION BY y ORDER BY para rankings, acumulados o comparaciones.","pitfall":"Confundir ventana con agregado puede eliminar detalle necesario.","difficulty":"Alta","sourceIds":["postgres"]},{"id":"bases-sistemas-08","domain":"bases-sistemas","term":"Índice","topic":"Rendimiento","definition":"Estructura auxiliar que acelera ciertos accesos a costa de almacenamiento y escritura.","scenario":"Una búsqueda frecuente por número de identificación es lenta.","application":"Crea índices guiado por patrones de consulta y planes de ejecución.","pitfall":"Indexar todo aumenta costo de escritura y mantenimiento.","difficulty":"Media","sourceIds":["postgres"]},{"id":"bases-sistemas-09","domain":"bases-sistemas","term":"Transacción","topic":"Consistencia","definition":"Unidad lógica de trabajo que se confirma o revierte como conjunto.","scenario":"Crear un registro implica insertar cabecera, detalle y auditoría.","application":"Agrupa cambios dependientes y maneja commit/rollback correctamente.","pitfall":"Transacciones demasiado largas aumentan bloqueos y contención.","difficulty":"Media","sourceIds":["postgres"]},{"id":"bases-sistemas-10","domain":"bases-sistemas","term":"ACID","topic":"Consistencia","definition":"Atomicidad, consistencia, aislamiento y durabilidad describen garantías transaccionales.","scenario":"Un fallo no debe dejar una operación financiera parcialmente aplicada.","application":"Diseña operaciones respetando reglas y el nivel de aislamiento necesario.","pitfall":"ACID no sustituye validaciones de negocio ni diseño correcto.","difficulty":"Media","sourceIds":["postgres"]},{"id":"bases-sistemas-11","domain":"bases-sistemas","term":"Nivel de aislamiento","topic":"Concurrencia","definition":"Controla qué interferencias entre transacciones concurrentes se permiten.","scenario":"Dos usuarios actualizan datos relacionados al mismo tiempo.","application":"Elige equilibrio entre consistencia y concurrencia según riesgos del proceso.","pitfall":"Aumentar aislamiento indiscriminadamente puede reducir rendimiento.","difficulty":"Alta","sourceIds":["postgres"]},{"id":"bases-sistemas-12","domain":"bases-sistemas","term":"Requisito funcional","topic":"Ingeniería de software","definition":"Describe qué comportamiento o servicio debe ofrecer el sistema.","scenario":"El sistema debe permitir registrar y consultar organizaciones.","application":"Redáctalo verificable y vincúlalo con criterios de aceptación.","pitfall":"Confundir solución técnica con necesidad puede restringir alternativas.","difficulty":"Básica","sourceIds":[]},{"id":"bases-sistemas-13","domain":"bases-sistemas","term":"Requisito no funcional","topic":"Ingeniería de software","definition":"Describe atributos de calidad o restricciones como seguridad, disponibilidad y rendimiento.","scenario":"El 95 % de consultas debe responder bajo un umbral acordado.","application":"Define métricas y condiciones verificables.","pitfall":"Decir 'debe ser rápido y seguro' sin métricas dificulta validar.","difficulty":"Media","sourceIds":[]},{"id":"bases-sistemas-14","domain":"bases-sistemas","term":"Pruebas de integración","topic":"Calidad","definition":"Verifican interacción entre componentes o servicios.","scenario":"La API debe guardar datos y consultar correctamente la base.","application":"Prueba contratos, errores y efectos reales entre capas.","pitfall":"Muchas pruebas unitarias no sustituyen probar integraciones críticas.","difficulty":"Media","sourceIds":[]},{"id":"bases-sistemas-15","domain":"bases-sistemas","term":"Rollback y observabilidad","topic":"Operación","definition":"Rollback revierte un despliegue; observabilidad permite entender el estado mediante logs, métricas y trazas.","scenario":"Una nueva versión aumenta errores en producción.","application":"Monitorea después del despliegue y conserva una ruta de reversión probada.","pitfall":"Desplegar sin métricas ni rollback convierte incidentes pequeños en fallas prolongadas.","difficulty":"Alta","sourceIds":[]},{"id":"gobierno-datos-01","domain":"gobierno-datos","term":"Data Owner","topic":"Gobierno","definition":"Rol responsable por decisiones y responsabilidad de negocio sobre un dominio o activo de datos.","scenario":"Debe definirse quién autoriza reglas y acceso para datos de un proceso.","application":"Asigna accountability y decisiones, no solo tareas operativas.","pitfall":"Confundir owner con administrador técnico diluye responsabilidad.","difficulty":"Media","sourceIds":[]},{"id":"gobierno-datos-02","domain":"gobierno-datos","term":"Data Steward","topic":"Gobierno","definition":"Rol que impulsa definiciones, calidad, metadatos y reglas operativas de datos.","scenario":"Se detectan definiciones distintas del mismo indicador entre áreas.","application":"Coordina estándares, calidad y resolución de problemas con negocio y tecnología.","pitfall":"El steward no reemplaza automáticamente al dueño del dato.","difficulty":"Media","sourceIds":[]},{"id":"gobierno-datos-03","domain":"gobierno-datos","term":"Custodio técnico","topic":"Gobierno","definition":"Rol encargado de controles técnicos de almacenamiento, disponibilidad y protección.","scenario":"La plataforma requiere backups, permisos y cifrado.","application":"Implementa controles conforme a decisiones de gobierno y seguridad.","pitfall":"Custodia técnica no implica decidir el uso legítimo del dato.","difficulty":"Media","sourceIds":[]},{"id":"gobierno-datos-04","domain":"gobierno-datos","term":"Catálogo de datos","topic":"Metadatos","definition":"Inventario navegable de activos con definiciones, propietarios, linaje y contexto.","scenario":"Analistas no saben qué tabla contiene la definición oficial de un indicador.","application":"Publica metadatos útiles, responsables y estado de calidad.","pitfall":"Un catálogo sin mantenimiento se vuelve obsoleto rápidamente.","difficulty":"Básica","sourceIds":[]},{"id":"gobierno-datos-05","domain":"gobierno-datos","term":"Completitud","topic":"Calidad","definition":"Grado en que los valores requeridos están presentes.","scenario":"Muchos registros carecen de municipio obligatorio.","application":"Mide porcentaje de campos requeridos presentes y define umbrales.","pitfall":"Completo no significa necesariamente correcto.","difficulty":"Básica","sourceIds":[]},{"id":"gobierno-datos-06","domain":"gobierno-datos","term":"Consistencia","topic":"Calidad","definition":"Grado en que datos relacionados no se contradicen entre sí o entre fuentes.","scenario":"Un código territorial corresponde a un municipio diferente según dos tablas.","application":"Define reglas de coherencia y una fuente autorizada para resolver conflictos.","pitfall":"Dos fuentes pueden ser válidas en momentos distintos; la temporalidad importa.","difficulty":"Media","sourceIds":[]},{"id":"gobierno-datos-07","domain":"gobierno-datos","term":"Interoperabilidad","topic":"Intercambio","definition":"Capacidad de sistemas y organizaciones para intercambiar y usar información con significado compartido.","scenario":"Dos entidades deben integrar registros sin redefinir manualmente cada campo.","application":"Alinea semántica, identificadores, formatos, APIs, seguridad y acuerdos.","pitfall":"Conectar dos APIs no garantiza interoperabilidad semántica.","difficulty":"Alta","sourceIds":[]},{"id":"gobierno-datos-08","domain":"gobierno-datos","term":"Dato abierto","topic":"Datos abiertos","definition":"Dato público dispuesto para uso y reutilización, sujeto al marco aplicable y condiciones de calidad/publicación.","scenario":"Una entidad publica conjuntos reutilizables para ciudadanía e investigación.","application":"Prioriza formatos procesables, metadatos, calidad y actualización.","pitfall":"Datos personales o reservados no se vuelven abiertos por conveniencia técnica.","difficulty":"Media","sourceIds":["datos-abiertos","ley1712"]},{"id":"gobierno-datos-09","domain":"gobierno-datos","term":"Máxima publicidad","topic":"Transparencia","definition":"Principio según el cual la información bajo control de sujetos obligados se presume pública salvo excepción constitucional o legal.","scenario":"Se recibe una solicitud de acceso a información institucional.","application":"Parte de la publicidad como regla y analiza restricciones únicamente con fundamento válido.","pitfall":"Tratar toda información institucional como reservada contradice el principio.","difficulty":"Media","sourceIds":["ley1712"]},{"id":"gobierno-datos-10","domain":"gobierno-datos","term":"Información clasificada","topic":"Transparencia","definition":"Información pública cuyo acceso puede exceptuarse por afectar derechos particulares o privados en los términos legales.","scenario":"Un documento contiene datos privados de una persona.","application":"Evalúa la excepción aplicable y considera versión pública de lo no protegido.","pitfall":"Clasificada y reservada no son categorías idénticas.","difficulty":"Alta","sourceIds":["ley1712"]},{"id":"gobierno-datos-11","domain":"gobierno-datos","term":"Información reservada","topic":"Transparencia","definition":"Información exceptuada de acceso por protección de intereses públicos bajo requisitos legales.","scenario":"Una autoridad invoca una reserva expresamente prevista en la ley.","application":"Motiva la reserva, limita su alcance y protege solo la parte indispensable.","pitfall":"La mera incomodidad institucional no crea una reserva.","difficulty":"Alta","sourceIds":["ley1712"]},{"id":"gobierno-datos-12","domain":"gobierno-datos","term":"Divulgación proactiva","topic":"Transparencia","definition":"Deber de publicar rutinariamente información de interés público, no solo responder solicitudes.","scenario":"La entidad dispone de indicadores de alto interés ciudadano.","application":"Diseña publicación actualizada, accesible y comprensible.","pitfall":"Esperar siempre una petición desaprovecha el principio de transparencia activa.","difficulty":"Media","sourceIds":["ley1712"]},{"id":"gobierno-datos-13","domain":"gobierno-datos","term":"Principio de finalidad","topic":"Datos personales","definition":"El tratamiento de datos debe obedecer a una finalidad legítima informada al titular cuando corresponda.","scenario":"Datos recogidos para un trámite se quieren reutilizar para otro propósito no previsto.","application":"Verifica compatibilidad jurídica y finalidad antes de reutilizar.","pitfall":"Tener acceso técnico a un dato no autoriza cualquier uso.","difficulty":"Media","sourceIds":["sic-datos"]},{"id":"gobierno-datos-14","domain":"gobierno-datos","term":"Circulación restringida","topic":"Datos personales","definition":"El tratamiento y circulación de datos personales debe respetar límites y autorizaciones aplicables.","scenario":"Un dataset con información personal se propone publicar en Internet.","application":"Controla acceso y evita divulgación masiva salvo habilitación legal o naturaleza pública del dato.","pitfall":"Anonimizar mal puede permitir reidentificación.","difficulty":"Alta","sourceIds":["sic-datos"]},{"id":"gobierno-datos-15","domain":"gobierno-datos","term":"Anonimización","topic":"Privacidad","definition":"Transformación orientada a reducir razonablemente la posibilidad de identificar personas en un conjunto.","scenario":"Se quiere publicar estadísticas detalladas derivadas de microdatos personales.","application":"Evalúa riesgo de reidentificación, granularidad y combinación con otras fuentes.","pitfall":"Eliminar nombre y cédula no garantiza anonimato si quedan identificadores indirectos.","difficulty":"Alta","sourceIds":["sic-datos"]},{"id":"derecho-01","domain":"derecho","term":"Principio de legalidad","topic":"Derecho administrativo","definition":"La actuación administrativa debe sujetarse a la Constitución, la ley y competencias atribuidas.","scenario":"Un área quiere adoptar una medida sin soporte normativo ni competencia definida.","application":"Identifica fundamento, competencia y procedimiento antes de actuar.","pitfall":"Una finalidad conveniente no sustituye habilitación jurídica.","difficulty":"Media","sourceIds":["cpaca"]},{"id":"derecho-02","domain":"derecho","term":"Competencia administrativa","topic":"Derecho administrativo","definition":"Atribución jurídica que habilita a una autoridad para actuar sobre determinada materia.","scenario":"Una dependencia recibe una solicitud que corresponde legalmente a otra.","application":"Verifica órgano, materia, territorio y grado antes de decidir.","pitfall":"La experiencia técnica de un funcionario no le otorga competencia jurídica.","difficulty":"Media","sourceIds":["cpaca"]},{"id":"derecho-03","domain":"derecho","term":"Debido proceso administrativo","topic":"Derecho administrativo","definition":"Garantía de actuación con reglas, oportunidad de defensa y decisiones conforme al procedimiento aplicable.","scenario":"Una decisión puede afectar derechos de una persona.","application":"Respeta notificación, contradicción, pruebas y motivación según el procedimiento.","pitfall":"La urgencia no elimina garantías sin fundamento legal.","difficulty":"Alta","sourceIds":["cpaca"]},{"id":"derecho-04","domain":"derecho","term":"Motivación","topic":"Derecho administrativo","definition":"Exposición de fundamentos fácticos y jurídicos que sostienen una decisión cuando es exigible.","scenario":"Una autoridad adopta una decisión desfavorable basada en un análisis.","application":"Documenta hechos, normas, evidencia y razonamiento pertinente.","pitfall":"Citar normas sin conectar con hechos no constituye una motivación sólida.","difficulty":"Media","sourceIds":["cpaca"]},{"id":"derecho-05","domain":"derecho","term":"Principio de eficacia","topic":"Derecho administrativo","definition":"Orienta la actuación a lograr la finalidad y efectividad de derechos evitando formalismos innecesarios.","scenario":"Un trámite se estanca por pasos que no aportan a la decisión.","application":"Simplifica dentro de la ley y prioriza solución material del asunto.","pitfall":"Eficacia no autoriza omitir controles esenciales.","difficulty":"Media","sourceIds":["cpaca"]},{"id":"derecho-06","domain":"derecho","term":"Principio de celeridad","topic":"Derecho administrativo","definition":"Exige impulso oportuno y diligente de actuaciones administrativas.","scenario":"Un expediente lleva semanas sin actividad por desorganización interna.","application":"Gestiona tiempos, prioridades y responsables sin sacrificar garantías.","pitfall":"Celeridad no significa decidir sin evidencia suficiente.","difficulty":"Básica","sourceIds":["cpaca"]},{"id":"derecho-07","domain":"derecho","term":"Acceso a información pública","topic":"Transparencia","definition":"Derecho de solicitar y recibir información pública de sujetos obligados bajo reglas y excepciones legales.","scenario":"Un ciudadano pide un conjunto de datos institucional.","application":"Identifica si es público, clasificado o reservado y responde de forma oportuna y motivada.","pitfall":"No puede exigirse una motivación innecesaria al solicitante.","difficulty":"Media","sourceIds":["ley1712"]},{"id":"derecho-08","domain":"derecho","term":"Versión pública","topic":"Transparencia","definition":"Documento que divulga las partes accesibles y protege únicamente la información legalmente exceptuada.","scenario":"Un informe mezcla información pública con datos protegidos.","application":"Oculta solo la parte indispensable y entrega el resto cuando sea jurídicamente procedente.","pitfall":"Negar todo el documento cuando solo una sección está protegida puede ser desproporcionado.","difficulty":"Alta","sourceIds":["ley1712"]},{"id":"derecho-09","domain":"derecho","term":"Habeas data","topic":"Datos personales","definition":"Facultad del titular de conocer, actualizar y rectificar información personal y garantías asociadas al tratamiento.","scenario":"Una persona detecta un dato personal inexacto en un sistema.","application":"Habilita canales para consulta, actualización y corrección conforme al régimen aplicable.","pitfall":"La información almacenada por una entidad no deja de estar sujeta a derechos del titular.","difficulty":"Media","sourceIds":["sic-datos"]},{"id":"derecho-10","domain":"derecho","term":"Responsable del tratamiento","topic":"Datos personales","definition":"Quien decide sobre la base de datos o el tratamiento y sus finalidades/medios esenciales.","scenario":"Una entidad define por qué y para qué se recolectan datos de un registro.","application":"Determina finalidad, controles y cumplimiento aplicable.","pitfall":"Externalizar tecnología no transfiere automáticamente toda responsabilidad.","difficulty":"Media","sourceIds":["sic-datos"]},{"id":"derecho-11","domain":"derecho","term":"Encargado del tratamiento","topic":"Datos personales","definition":"Quien realiza tratamiento por cuenta del responsable.","scenario":"Un proveedor opera una plataforma que procesa datos definidos por la entidad.","application":"Debe actuar conforme a instrucciones y obligaciones aplicables al tratamiento.","pitfall":"Encargado no debe usar datos para fines propios no autorizados.","difficulty":"Media","sourceIds":["sic-datos"]},{"id":"derecho-12","domain":"derecho","term":"Consentimiento informado","topic":"Datos personales","definition":"Autorización previa, expresa e informada cuando el tratamiento la requiere y no aplica una excepción legal.","scenario":"Se diseña un formulario para una finalidad no cubierta por habilitación legal específica.","application":"Informa finalidad y condiciones antes de obtener autorización cuando corresponda.","pitfall":"Una casilla preseleccionada o finalidad oculta puede ser problemática.","difficulty":"Alta","sourceIds":["sic-datos"]},{"id":"derecho-13","domain":"derecho","term":"Documento electrónico","topic":"Derecho informático","definition":"Información generada, enviada, recibida o almacenada por medios electrónicos que puede tener efectos jurídicos bajo condiciones aplicables.","scenario":"Un procedimiento se soporta en expedientes y comunicaciones digitales.","application":"Preserva autenticidad, integridad, disponibilidad y trazabilidad según el caso.","pitfall":"Digitalizar un archivo no garantiza por sí mismo integridad o autenticidad.","difficulty":"Media","sourceIds":[]},{"id":"derecho-14","domain":"derecho","term":"Proporcionalidad","topic":"Principios","definition":"Exige que una medida restrictiva sea adecuada, necesaria y equilibrada respecto del fin legítimo.","scenario":"Se propone recolectar datos muy intrusivos para un objetivo menor.","application":"Evalúa si existe una alternativa menos restrictiva que logre el propósito.","pitfall":"Recolectar 'por si acaso' contradice minimización y proporcionalidad.","difficulty":"Alta","sourceIds":[]},{"id":"derecho-15","domain":"derecho","term":"Trazabilidad de decisión","topic":"Gobernanza jurídica","definition":"Capacidad de reconstruir quién decidió, con qué evidencia, norma y versión de información.","scenario":"Una decisión apoyada por analítica debe ser revisada posteriormente.","application":"Conserva evidencia, fuente de datos, criterios y responsables.","pitfall":"Un resultado algorítmico sin trazabilidad dificulta control y defensa de decisiones.","difficulty":"Alta","sourceIds":[]},{"id":"contratacion-01","domain":"contratacion","term":"Principio de planeación","topic":"Planeación contractual","definition":"La contratación debe partir de una necesidad definida y análisis suficiente para estructurar el proceso.","scenario":"Se requiere una plataforma analítica institucional.","application":"Define necesidad, alcance, alternativas, presupuesto, riesgos y estrategia antes de seleccionar.","pitfall":"Usar la contratación para 'descubrir' qué se necesita aumenta riesgos de ejecución.","difficulty":"Media","sourceIds":["ley80","ley1150","cce-manual"]},{"id":"contratacion-02","domain":"contratacion","term":"Estudios previos","topic":"Planeación contractual","definition":"Documento de soporte que justifica necesidad y condiciones técnicas, económicas y jurídicas del proceso.","scenario":"Una dependencia inicia adquisición de servicios tecnológicos.","application":"Sustenta necesidad, objeto, valor, modalidad, riesgos y demás elementos exigibles.","pitfall":"Copiar estudios de otro proceso sin análisis propio debilita la planeación.","difficulty":"Media","sourceIds":["decreto1082","cce-manual"]},{"id":"contratacion-03","domain":"contratacion","term":"Análisis del sector","topic":"Planeación contractual","definition":"Estudio del mercado y contexto para entender oferta, precios, riesgos y condiciones del bien o servicio.","scenario":"Se contratará almacenamiento en nube con múltiples modelos de precio.","application":"Analiza mercado, proveedores, alternativas, costos y dinámica del sector.","pitfall":"Solicitar tres cotizaciones no agota necesariamente un análisis del sector.","difficulty":"Alta","sourceIds":["cce-manual"]},{"id":"contratacion-04","domain":"contratacion","term":"Plan Anual de Adquisiciones","topic":"Planeación contractual","definition":"Instrumento de planeación y publicidad de necesidades de bienes, obras y servicios proyectados.","scenario":"Una compra tecnológica aparece como necesidad recurrente para el siguiente año.","application":"Alinea programación de adquisiciones con planeación y actualízalo cuando corresponda.","pitfall":"Publicarlo no reemplaza estudios previos ni obliga a contratar todo lo listado.","difficulty":"Media","sourceIds":["cce-manual"]},{"id":"contratacion-05","domain":"contratacion","term":"Selección objetiva","topic":"Selección","definition":"Elección basada en factores y reglas previamente definidos, evitando preferencias subjetivas.","scenario":"Dos proponentes cumplen, pero uno tiene relación previa con el equipo.","application":"Aplica criterios verificables del proceso y documenta la evaluación.","pitfall":"Cambiar criterios después de recibir ofertas afecta transparencia e igualdad.","difficulty":"Alta","sourceIds":["ley1150"]},{"id":"contratacion-06","domain":"contratacion","term":"Licitación pública","topic":"Modalidades","definition":"Modalidad que opera como regla general salvo que exista causal para otra modalidad.","scenario":"Una contratación no encaja en causal específica de selección abreviada, concurso, directa o mínima cuantía.","application":"Verifica régimen, cuantía y objeto antes de definir modalidad.","pitfall":"Elegir modalidad por comodidad puede vulnerar el marco aplicable.","difficulty":"Media","sourceIds":["ley1150"]},{"id":"contratacion-07","domain":"contratacion","term":"Selección abreviada","topic":"Modalidades","definition":"Modalidad prevista para causales en las que las características del objeto o circunstancias permiten procesos simplificados.","scenario":"Se evalúa una causal legal específica para adquisición de características uniformes.","application":"Verifica que la causal y procedimiento correspondan al caso.","pitfall":"No debe confundirse con contratación directa.","difficulty":"Media","sourceIds":["ley1150","decreto1082"]},{"id":"contratacion-08","domain":"contratacion","term":"Concurso de méritos","topic":"Modalidades","definition":"Modalidad orientada a selección de consultores/proyectos en los eventos definidos por la regulación.","scenario":"Se requiere una consultoría especializada para estudios técnicos.","application":"Analiza si el objeto corresponde a consultoría y aplica reglas específicas.","pitfall":"Un contrato de servicios profesionales no se convierte automáticamente en concurso de méritos.","difficulty":"Alta","sourceIds":["ley1150","decreto1082"]},{"id":"contratacion-09","domain":"contratacion","term":"Contratación directa","topic":"Modalidades","definition":"Modalidad excepcional aplicable únicamente bajo causales legalmente previstas.","scenario":"Se considera contratar sin proceso competitivo por una causal alegada.","application":"Verifica causal, justificación y requisitos documentales antes de usarla.","pitfall":"La urgencia administrativa o preferencia por un proveedor no crea por sí sola causal.","difficulty":"Alta","sourceIds":["ley1150","decreto1082"]},{"id":"contratacion-10","domain":"contratacion","term":"Mínima cuantía","topic":"Modalidades","definition":"Procedimiento aplicable cuando el valor no excede el umbral legal correspondiente, independientemente del objeto bajo sus reglas.","scenario":"Una adquisición de bajo monto requiere proceso simplificado.","application":"Verifica cuantía vigente, estudios mínimos y procedimiento aplicable.","pitfall":"Bajo valor no significa ausencia de planeación o publicidad.","difficulty":"Media","sourceIds":["decreto1082"]},{"id":"contratacion-11","domain":"contratacion","term":"Matriz de riesgos","topic":"Riesgos","definition":"Identifica, asigna y trata eventos que pueden afectar el proceso y ejecución contractual.","scenario":"Un proyecto de datos depende de migración, disponibilidad y calidad de fuentes.","application":"Define riesgo, probabilidad, impacto, asignación y tratamiento.","pitfall":"Confundir una obligación normal del contratista con un riesgo dificulta gestión.","difficulty":"Media","sourceIds":["cce-manual"]},{"id":"contratacion-12","domain":"contratacion","term":"Supervisión","topic":"Ejecución","definition":"Seguimiento técnico, administrativo, financiero, contable y jurídico que realiza la entidad cuando no requiere interventoría externa según el caso.","scenario":"Un contrato de software necesita control de entregables y SLA.","application":"Define supervisor y documenta cumplimiento, alertas y decisiones.","pitfall":"Firmar informes sin verificar evidencia vacía de sentido la supervisión.","difficulty":"Media","sourceIds":["cce-manual"]},{"id":"contratacion-13","domain":"contratacion","term":"Interventoría","topic":"Ejecución","definition":"Seguimiento especializado contratado cuando la ley o naturaleza del contrato lo requiere, con alcance definido.","scenario":"Una obra o proyecto complejo requiere control técnico independiente.","application":"Diferencia funciones frente a supervisión y evita duplicidades o vacíos.","pitfall":"Interventoría y supervisión no son sinónimos automáticos.","difficulty":"Alta","sourceIds":["ley80","cce-manual"]},{"id":"contratacion-14","domain":"contratacion","term":"Modificación contractual","topic":"Ejecución","definition":"Cambio jurídicamente sustentado que debe respetar límites, finalidad, competencia y justificación.","scenario":"Durante ejecución se solicita ampliar alcance de una solución tecnológica.","application":"Analiza necesidad, soporte, disponibilidad, límites y efectos antes de modificar.","pitfall":"Usar modificaciones para alterar esencialmente el objeto puede ser improcedente.","difficulty":"Alta","sourceIds":["ley80","cce-manual"]},{"id":"contratacion-15","domain":"contratacion","term":"Liquidación","topic":"Cierre","definition":"Etapa o acto mediante el cual se realiza balance final de obligaciones cuando corresponde.","scenario":"Al terminar un contrato quedan saldos, entregables y obligaciones por verificar.","application":"Consolida estado financiero, técnico y jurídico según régimen y condiciones.","pitfall":"Cerrar operativamente sin documentar pendientes puede generar disputas posteriores.","difficulty":"Media","sourceIds":["ley80","cce-manual"]},{"id":"pgn-01","domain":"pgn","term":"Ministerio Público","topic":"Naturaleza institucional","definition":"Función constitucional ejercida por órganos como la Procuraduría, Defensoría y personerías dentro de sus competencias.","scenario":"Se ubica institucionalmente a la PGN frente a otras ramas y órganos.","application":"Comprende que la PGN es máximo organismo del Ministerio Público, no una dependencia del Ejecutivo.","pitfall":"Confundir Ministerio Público con un ministerio del Gobierno cambia su naturaleza institucional.","difficulty":"Básica","sourceIds":["pgn-funciones","decreto262"]},{"id":"pgn-02","domain":"pgn","term":"Autonomía de la PGN","topic":"Naturaleza institucional","definition":"La PGN tiene autonomía administrativa, financiera y presupuestal en los términos aplicables.","scenario":"Se analiza quién define decisiones internas de gestión dentro de su marco legal.","application":"Distingue autonomía institucional de ausencia de controles jurídicos o presupuestales.","pitfall":"Autonomía no significa actuar fuera de la Constitución y la ley.","difficulty":"Media","sourceIds":["pgn-funciones","decreto262"]},{"id":"pgn-03","domain":"pgn","term":"Función preventiva","topic":"Funciones misionales","definition":"Busca prevenir irregularidades vigilando la actuación pública y advirtiendo riesgos sin coadministrar.","scenario":"Se identifican riesgos de incumplimiento antes de que ocurra una falta.","application":"La analítica puede priorizar alertas y seguimiento sin sustituir a la autoridad competente.","pitfall":"Preventivo no significa imponer directamente la gestión a otra entidad.","difficulty":"Media","sourceIds":["pgn-funciones"]},{"id":"pgn-04","domain":"pgn","term":"Función de intervención","topic":"Funciones misionales","definition":"Intervención de la PGN como sujeto procesal ante jurisdicciones y autoridades en los casos establecidos.","scenario":"Un proceso judicial requiere participación del Ministerio Público dentro de sus competencias.","application":"Diferencia intervención procesal de investigación disciplinaria.","pitfall":"Intervención no es simplemente asesoría tecnológica o administrativa.","difficulty":"Media","sourceIds":["pgn-funciones"]},{"id":"pgn-05","domain":"pgn","term":"Función disciplinaria","topic":"Funciones misionales","definition":"Comprende iniciar, adelantar y fallar investigaciones disciplinarias dentro del marco aplicable.","scenario":"Se analiza una conducta atribuida a servidor público o particular disciplinable.","application":"La información y analítica apoyan, pero las decisiones siguen procedimientos y competencias.","pitfall":"Un indicador de riesgo no constituye por sí mismo responsabilidad disciplinaria.","difficulty":"Media","sourceIds":["pgn-funciones"]},{"id":"pgn-06","domain":"pgn","term":"Estructura orgánica","topic":"Organización","definition":"Distribución formal de dependencias y niveles para ejercer funciones institucionales.","scenario":"Un proyecto requiere identificar la dependencia competente y canales de coordinación.","application":"Consulta estructura vigente y funciones específicas antes de asignar responsabilidades.","pitfall":"Usar organigramas antiguos puede llevar a errores tras modificaciones normativas.","difficulty":"Alta","sourceIds":["decreto262","decreto1851","manual-pgn-v9"]},{"id":"pgn-07","domain":"pgn","term":"Dirección de Apoyo Estratégico, Análisis de Datos e Información","topic":"Convocatoria 217","definition":"Dependencia asociada al empleo 217-2026 y al uso estratégico de información y analítica.","scenario":"Se diseña una solución analítica para apoyar decisiones de alta dirección.","application":"Conecta tecnología, datos, innovación y contexto institucional.","pitfall":"Reducir el rol a operación de bases de datos ignora su componente estratégico.","difficulty":"Alta","sourceIds":["conv217","manual-pgn-v9"]},{"id":"pgn-08","domain":"pgn","term":"Propósito del empleo 217","topic":"Convocatoria 217","definition":"Apoyar profesionalmente innovación y desarrollo tecnológico en ciencias de datos, tecnologías emergentes y análisis de información para decisiones.","scenario":"Se prioriza qué capacidades estudiar para el concurso.","application":"Integra datos, innovación, sistemas y toma de decisiones, no un único lenguaje o herramienta.","pitfall":"Prepararse solo en SQL dejaría vacíos jurídicos, de gobierno y analítica.","difficulty":"Media","sourceIds":["conv217"]},{"id":"pgn-09","domain":"pgn","term":"Analítica e inteligencia de negocios","topic":"Convocatoria 217","definition":"La convocatoria incluye diseño, desarrollo, pruebas y puesta en producción de soluciones de analítica y BI.","scenario":"Un dashboard estratégico debe pasar de prototipo a solución confiable.","application":"Estudia ciclo completo: datos, modelo, prueba, visualización, despliegue y adopción.","pitfall":"Confundir BI con solo gráficos ignora modelado, calidad y decisión.","difficulty":"Alta","sourceIds":["conv217"]},{"id":"pgn-10","domain":"pgn","term":"Investigación tecnológica","topic":"Convocatoria 217","definition":"Exploración y evaluación de herramientas, métodos o tecnologías para resolver necesidades institucionales.","scenario":"Se considera incorporar una tecnología emergente a un proceso de análisis.","application":"Evalúa evidencia, seguridad, costo, interoperabilidad y valor antes de adoptar.","pitfall":"Usar tecnología por moda no constituye innovación útil.","difficulty":"Alta","sourceIds":["conv217"]},{"id":"pgn-11","domain":"pgn","term":"Instrumentos metodológicos","topic":"Convocatoria 217","definition":"Métodos, lineamientos y artefactos que permiten hacer reproducible y defendible el trabajo técnico.","scenario":"Un equipo necesita estandarizar análisis de datos entre proyectos.","application":"Define procedimientos, criterios, documentación y controles comunes.","pitfall":"Una metodología demasiado abstracta que nadie aplica aporta poco valor.","difficulty":"Media","sourceIds":["conv217"]},{"id":"pgn-12","domain":"pgn","term":"Bases de datos y sistemas de información en la 217","topic":"Conocimientos esenciales","definition":"La convocatoria exige comprender manejo de bases de datos y sistemas de información.","scenario":"Una solución de analítica consume múltiples sistemas misionales.","application":"Conecta integridad, arquitectura, interoperabilidad y calidad antes de visualizar.","pitfall":"Saber escribir consultas no sustituye entender el sistema fuente y semántica.","difficulty":"Media","sourceIds":["conv217"]},{"id":"pgn-13","domain":"pgn","term":"Gobierno, transparencia y datos abiertos en la 217","topic":"Conocimientos esenciales","definition":"La convocatoria incorpora gobierno de transparencia y datos abiertos como conocimiento esencial.","scenario":"Se evalúa publicar o reutilizar información institucional.","application":"Equilibra apertura, calidad, protección y finalidad legal.","pitfall":"Asumir que todo dato estatal es automáticamente abierto es incorrecto.","difficulty":"Alta","sourceIds":["conv217","ley1712","datos-abiertos"]},{"id":"pgn-14","domain":"pgn","term":"Contratación estatal en la 217","topic":"Conocimientos esenciales","definition":"La convocatoria incluye contratación estatal dentro del conocimiento requerido.","scenario":"Un profesional de datos participa en especificaciones o seguimiento de soluciones contratadas.","application":"Comprende planeación, requisitos, riesgos, supervisión y trazabilidad contractual.","pitfall":"El perfil técnico no exime de entender el contexto contractual público.","difficulty":"Media","sourceIds":["conv217","cce-manual"]},{"id":"pgn-15","domain":"pgn","term":"Decisión basada en información","topic":"Valor del cargo","definition":"Uso de evidencia de calidad para apoyar decisiones sin reemplazar juicio, competencia ni responsabilidad de la alta dirección.","scenario":"Un modelo identifica patrones que sugieren priorizar una intervención.","application":"Presenta evidencia, incertidumbre, limitaciones y trazabilidad para que la autoridad decida.","pitfall":"Automatizar una recomendación no convierte al modelo en autoridad decisora.","difficulty":"Alta","sourceIds":["conv217"]},{"id":"comportamental-01","domain":"comportamental","term":"Responsabilidad con la organización","topic":"Competencias","definition":"Actuar protegiendo objetivos, recursos, normas y confianza institucional.","scenario":"Detectas un error en un informe ya próximo a enviarse.","application":"Informa oportunamente, corrige con trazabilidad y evita ocultar el problema.","pitfall":"Proteger la imagen no significa esconder errores.","difficulty":"Media","sourceIds":["conv217"]},{"id":"comportamental-02","domain":"comportamental","term":"Organización del trabajo","topic":"Competencias","definition":"Planificar, priorizar y controlar actividades para cumplir con calidad y plazo.","scenario":"Recibes tres tareas críticas con dependencias diferentes.","application":"Ordena por impacto, urgencia, dependencia y capacidad; comunica compromisos.","pitfall":"Atender solo lo más reciente puede desplazar tareas realmente críticas.","difficulty":"Media","sourceIds":["conv217"]},{"id":"comportamental-03","domain":"comportamental","term":"Investigación","topic":"Competencias","definition":"Buscar, contrastar y analizar información antes de concluir.","scenario":"Una inconsistencia aparece en un indicador estratégico.","application":"Rastrea fuente, reglas, transformaciones y evidencia antes de afirmar la causa.","pitfall":"Quedarse con la primera explicación plausible aumenta errores.","difficulty":"Media","sourceIds":["conv217"]},{"id":"comportamental-04","domain":"comportamental","term":"Pensamiento conceptual","topic":"Competencias","definition":"Identificar patrones, principios y relaciones para comprender problemas complejos.","scenario":"Varias fallas aparentemente distintas tienen un mismo origen en calidad de datos.","application":"Construye un modelo mental causal y distingue síntomas de causas.","pitfall":"Resolver cada síntoma aisladamente puede perpetuar el problema estructural.","difficulty":"Alta","sourceIds":["conv217"]},{"id":"comportamental-05","domain":"comportamental","term":"Orientación a resultados","topic":"Competencias","definition":"Dirigir esfuerzos a resultados verificables sin sacrificar integridad ni calidad.","scenario":"Un proyecto tiene muchas reuniones pero pocos entregables.","application":"Define producto, criterio de aceptación, responsable y fecha.","pitfall":"Confundir actividad con resultado genera falsa sensación de avance.","difficulty":"Media","sourceIds":["conv217"]},{"id":"comportamental-06","domain":"comportamental","term":"Cumplimiento de parámetros","topic":"Competencias","definition":"Trabajar dentro de estándares, procedimientos y criterios definidos.","scenario":"Un análisis urgente tiene un procedimiento institucional obligatorio.","application":"Cumple controles esenciales y propone mejoras por canales adecuados.","pitfall":"Saltarse controles sin autorización puede invalidar resultados.","difficulty":"Media","sourceIds":["conv217"]},{"id":"comportamental-07","domain":"comportamental","term":"Priorización por riesgo","topic":"Gestión","definition":"Asignar atención considerando impacto y probabilidad, no solo orden de llegada.","scenario":"Dos incidentes compiten: uno afecta dashboard menor y otro integridad de datos críticos.","application":"Prioriza el mayor riesgo y comunica la reprogramación del otro.","pitfall":"Urgencia percibida no siempre equivale a impacto real.","difficulty":"Alta","sourceIds":[]},{"id":"comportamental-08","domain":"comportamental","term":"Comunicación de riesgos","topic":"Gestión","definition":"Informar oportunamente incertidumbres, restricciones y posibles impactos a quienes deciden.","scenario":"Un dataset incompleto amenaza la fecha de un informe.","application":"Explica qué falta, impacto, opciones y recomendación, sin ocultar incertidumbre.","pitfall":"Decir 'todo está bien' para evitar conflicto transfiere riesgo a la decisión.","difficulty":"Media","sourceIds":[]},{"id":"comportamental-09","domain":"comportamental","term":"Trazabilidad","topic":"Gestión","definition":"Dejar evidencia suficiente de decisiones, cambios y responsables.","scenario":"Se modifica una regla de cálculo de un indicador.","application":"Registra versión, motivo, fecha, responsable y efecto esperado.","pitfall":"Depender de memoria o chats aislados dificulta auditoría.","difficulty":"Media","sourceIds":[]},{"id":"comportamental-10","domain":"comportamental","term":"Calidad bajo presión","topic":"Gestión","definition":"Mantener controles esenciales cuando el tiempo es limitado.","scenario":"La alta dirección solicita un reporte para el mismo día.","application":"Reduce alcance si es necesario, valida lo crítico y declara limitaciones.","pitfall":"Entregar rápido información no validada puede causar una decisión peor que entregar menos.","difficulty":"Alta","sourceIds":[]},{"id":"comportamental-11","domain":"comportamental","term":"Escalamiento adecuado","topic":"Gestión","definition":"Elevar un asunto cuando excede autoridad, riesgo aceptable o capacidad de resolución.","scenario":"Descubres un posible acceso indebido a datos sensibles.","application":"Preserva evidencia y escala por el canal definido de seguridad/autoridad.","pitfall":"Intentar resolver en secreto un incidente fuera de tu competencia puede agravar el riesgo.","difficulty":"Alta","sourceIds":[]},{"id":"comportamental-12","domain":"comportamental","term":"Trabajo colaborativo","topic":"Gestión","definition":"Coordinar conocimiento y responsabilidades entre perfiles para lograr un resultado común.","scenario":"Datos, jurídico y negocio discrepan sobre una publicación.","application":"Aclara objetivo, roles, criterios y evidencia; busca decisión documentada.","pitfall":"Imponer una visión técnica sin escuchar restricciones jurídicas genera soluciones inviables.","difficulty":"Media","sourceIds":[]},{"id":"comportamental-13","domain":"comportamental","term":"Decisión basada en evidencia","topic":"Gestión","definition":"Preferir información verificable y criterios explícitos frente a intuición no contrastada.","scenario":"Dos hipótesis compiten para explicar caída de un indicador.","application":"Define qué evidencia distinguiría las hipótesis y analízala.","pitfall":"Seleccionar la explicación favorita y buscar solo confirmación introduce sesgo.","difficulty":"Alta","sourceIds":[]},{"id":"comportamental-14","domain":"comportamental","term":"Uso ético de datos","topic":"Ética","definition":"Considerar derechos, finalidad, sesgos, seguridad y consecuencias de análisis o automatización.","scenario":"Un modelo parece útil pero usa variables que pueden generar impactos injustificados.","application":"Evalúa necesidad, legitimidad, sesgo, explicabilidad y controles antes de usarlo.","pitfall":"Buen desempeño estadístico no resuelve automáticamente riesgos éticos o jurídicos.","difficulty":"Alta","sourceIds":[]},{"id":"comportamental-15","domain":"comportamental","term":"Mejora continua","topic":"Gestión","definition":"Aprender de resultados y ajustar procesos mediante evidencia.","scenario":"Un simulacro o proyecto repite el mismo tipo de error.","application":"Registra causa, acción correctiva y verifica si disminuye recurrencia.","pitfall":"Cambiar muchas cosas a la vez impide saber qué mejora funcionó.","difficulty":"Media","sourceIds":[]}],"sources":[{"id":"conv217","title":"Convocatoria 217-2026 — versión 2","institution":"Procuraduría General de la Nación","kind":"Oficial convocatoria","verified":"2026-11-05","url":"https://www.procuraduria.gov.co/Documents/2026/Concurso-de-meritos/VERSI%C3%93N%202.%20CONVOCATORIAS%20CONCURSO%20DE%20M%C3%89RTOS%20RES%20108%20DEL%2023%20DE%20ABRIL%20DE%202026.pdf","notes":"Fuente primaria para propósito, funciones, requisitos y conocimientos esenciales del empleo 217-2026."},{"id":"manual-pgn-v9","title":"Manual específico de funciones por competencias laborales — V9 (19/02/2026)","institution":"Procuraduría General de la Nación","kind":"Oficial institucional","verified":"2026-11-05","url":"https://www.procuraduria.gov.co/Documents/2026/Febrero/Manual%20de%20Funciones_V9%20-%20230226.pdf","notes":"Manual institucional vigente publicado por la PGN para estudiar funciones y competencias."},{"id":"pgn-funciones","title":"Objetivos y funciones de la Procuraduría General de la Nación","institution":"Procuraduría General de la Nación","kind":"Oficial institucional","verified":"2026-11-05","url":"https://www.procuraduria.gov.co/procuraduria/conozca-entidad/Pages/objetivos-funciones.aspx","notes":"Describe las funciones misionales preventiva, de intervención y disciplinaria."},{"id":"decreto262","title":"Decreto Ley 262 de 2000","institution":"Función Pública","kind":"Normativa","verified":"2026-11-05","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=40618","notes":"Estructura, organización, competencias internas y funcionamiento de la PGN."},{"id":"decreto1851","title":"Decreto 1851 de 2021","institution":"Función Pública","kind":"Normativa","verified":"2026-11-05","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=175150","notes":"Modifica parcialmente los Decretos Ley 262 y 265 de 2000 y reconfigura estructura/planta."},{"id":"ley1712","title":"Ley 1712 de 2014 — Transparencia y acceso a la información pública","institution":"Función Pública","kind":"Normativa","verified":"2026-11-05","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=56882","notes":"Máxima publicidad, calidad de la información, divulgación proactiva, información clasificada y reservada."},{"id":"datos-abiertos","title":"Guía para el uso y aprovechamiento de Datos Abiertos en Colombia — versión 6","institution":"MinTIC — Gobierno Digital","kind":"Guía oficial","verified":"2026-11-05","url":"https://gobiernodigital.mintic.gov.co/692/articles-272749_recurso_1.pdf","notes":"Ciclo de datos abiertos, publicación, calidad, aprovechamiento y reutilización."},{"id":"sic-datos","title":"Política de Tratamiento de Datos Personales — principios Ley 1581 de 2012","institution":"Superintendencia de Industria y Comercio","kind":"Guía oficial","verified":"2026-11-05","url":"https://sedeelectronica.sic.gov.co/politica-de-tratamiento-de-datos-personales","notes":"Principios de legalidad, finalidad, libertad, veracidad/calidad, transparencia y circulación restringida."},{"id":"ley80","title":"Ley 80 de 1993 — Estatuto General de Contratación","institution":"Función Pública","kind":"Normativa","verified":"2026-11-05","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=304","notes":"Marco general de contratación estatal."},{"id":"ley1150","title":"Ley 1150 de 2007","institution":"Función Pública","kind":"Normativa","verified":"2026-11-05","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=184686","notes":"Eficiencia, transparencia, selección objetiva y modalidades de selección."},{"id":"decreto1082","title":"Decreto 1082 de 2015 — Sector Planeación Nacional","institution":"Función Pública","kind":"Normativa","verified":"2026-11-05","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=77653","notes":"Reglamentación integrada del sector y reglas aplicables a contratación pública."},{"id":"cpaca","title":"Ley 1437 de 2011 — CPACA","institution":"Función Pública","kind":"Normativa","verified":"2026-11-05","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=41249","notes":"Finalidad, ámbito, principios y procedimiento administrativo."},{"id":"cce-manual","title":"Manual de Contratación — ANCP Colombia Compra Eficiente","institution":"Colombia Compra Eficiente","kind":"Guía oficial","verified":"2026-11-05","url":"https://colombiacompra.gov.co/wp-content/uploads/2025/06/CCE-GCO-MA-01-MANUAL-DE-CONTRATACION-V07-24-07-2025-of.pdf","notes":"Planeación, estudios previos, modalidad, supervisión y gestión contractual."},{"id":"postgres","title":"PostgreSQL Documentation","institution":"PostgreSQL Global Development Group","kind":"Referencia técnica","verified":"2026-11-05","url":"https://www.postgresql.org/docs/current/","notes":"SQL, transacciones, índices y arquitectura de base de datos."},{"id":"sklearn","title":"scikit-learn User Guide","institution":"scikit-learn","kind":"Referencia técnica","verified":"2026-11-05","url":"https://scikit-learn.org/stable/user_guide.html","notes":"Aprendizaje supervisado/no supervisado, validación y métricas."},{"id":"python","title":"Python 3 Documentation","institution":"Python Software Foundation","kind":"Referencia técnica","verified":"2026-11-05","url":"https://docs.python.org/3/","notes":"Referencia de apoyo para conceptos y ejercicios de programación/análisis."}],"studyWeeks":[{"id":"w01","week":1,"title":"Diagnóstico y mapa personal","focus":["pgn","estadistica","derecho"],"goal":"Establecer línea base y detectar vacíos críticos.","activities":["Realizar diagnóstico de 36 preguntas.","Revisar estructura de la Convocatoria 217 y funciones del cargo.","Crear lista de 10 conceptos débiles.","Completar 2 lecciones de PGN y 1 de estadística."],"target":"Diagnóstico completo + 3 lecciones + bitácora inicial.","exam":"Mini práctica de 20 preguntas en los 3 dominios más débiles."},{"id":"w02","week":2,"title":"Estadística descriptiva y probabilidad","focus":["estadistica"],"goal":"Dominar lectura de datos, dispersión, percentiles y probabilidad.","activities":["Completar lecciones 1 y 2 de Estadística.","Resolver 30 preguntas de Estadística.","Realizar 4 retos numéricos.","Repasar 20 flashcards."],"target":"≥80 % en práctica básica/media.","exam":"Práctica de 30 preguntas de Estadística."},{"id":"w03","week":3,"title":"Inferencia y razonamiento estadístico","focus":["estadistica"],"goal":"Interpretar hipótesis, p-value, errores, efecto y regresión.","activities":["Completar lecciones 3 a 5 de Estadística.","Resolver retos numéricos restantes.","Explicar p-value sin mirar material.","Registrar errores de alta confianza."],"target":"≥80 % en inferencia y sin confundir p-value con probabilidad de H0.","exam":"Caso largo de Estadística + 25 preguntas."},{"id":"w04","week":4,"title":"Ciencia de datos: fundamentos y métricas","focus":["ciencia-datos"],"goal":"Dominar paradigma supervisado/no supervisado, validación y métricas.","activities":["Completar 3 lecciones de Ciencia de Datos.","Resolver 35 preguntas.","Comparar precision, recall, F1 y ROC-AUC.","Revisar 20 flashcards del dominio."],"target":"≥80 % y poder justificar métrica según costo del error.","exam":"Mini simulacro de 40 preguntas acumulativas."},{"id":"w05","week":5,"title":"Ciencia de datos: generalización y producción","focus":["ciencia-datos"],"goal":"Reconocer overfitting, leakage, drift y feature engineering.","activities":["Completar las lecciones restantes y caso integrador.","Resolver 30 preguntas media/alta.","Analizar un caso de fuga de datos.","Construir una matriz de riesgos de ML."],"target":"≥82 % en preguntas situacionales.","exam":"Caso largo de Ciencia de Datos."},{"id":"w06","week":6,"title":"Ingeniería de datos y arquitectura analítica","focus":["ingenieria-datos"],"goal":"Dominar ETL/ELT, pipelines, warehouse/lake/mart y modelado.","activities":["Completar 4 lecciones.","Dibujar de memoria un pipeline institucional.","Resolver 35 preguntas.","Resolver 4 retos de arquitectura."],"target":"Explicar trade-offs batch/streaming y warehouse/lake.","exam":"Práctica de 35 preguntas del dominio."},{"id":"w07","week":7,"title":"Calidad, metadatos y linaje","focus":["ingenieria-datos","gobierno-datos"],"goal":"Conectar calidad técnica con gobierno y trazabilidad.","activities":["Finalizar Ingeniería de Datos.","Completar 2 lecciones de Gobierno.","Resolver 30 preguntas.","Crear checklist de calidad para un dataset público."],"target":"≥82 % en calidad, metadatos y linaje.","exam":"Caso integrador de Ingeniería + Gobierno."},{"id":"w08","week":8,"title":"SQL, bases de datos y sistemas","focus":["bases-sistemas"],"goal":"Dominar modelo relacional, consultas, transacciones y requisitos.","activities":["Completar 4 lecciones de Bases/Sistemas.","Resolver 10 retos SQL.","Resolver 40 preguntas.","Repasar transacciones, ACID e índices."],"target":"≥85 % en SQL conceptual y consistencia.","exam":"Práctica de 40 preguntas + retos SQL."},{"id":"w09","week":9,"title":"Sistemas, pruebas y producción","focus":["bases-sistemas"],"goal":"Conectar requisitos, integración, pruebas, observabilidad y rollback.","activities":["Finalizar Bases/Sistemas.","Resolver caso largo de despliegue.","Hacer mapa mental del ciclo de solución.","Revisar errores acumulados."],"target":"≥85 % en casos de sistema.","exam":"Simulacro acumulativo de 60 preguntas."},{"id":"w10","week":10,"title":"Gobierno de datos y transparencia","focus":["gobierno-datos"],"goal":"Dominar roles, calidad, interoperabilidad, apertura y excepciones.","activities":["Completar Gobierno de Datos.","Estudiar Ley 1712 en módulo normativo.","Resolver 40 preguntas.","Comparar información pública, clasificada y reservada."],"target":"≥82 % y argumentación normativa básica.","exam":"Caso largo de publicación de datos."},{"id":"w11","week":11,"title":"Datos personales y derecho informático","focus":["derecho","gobierno-datos"],"goal":"Aplicar finalidad, libertad, calidad, transparencia y derechos del titular.","activities":["Completar 3 lecciones de Derecho.","Estudiar Ley 1581 artículo 4 y derechos del titular.","Resolver 35 preguntas.","Analizar un caso de reutilización de datos."],"target":"≥80 % en privacidad y acceso a información.","exam":"Práctica jurídica de 35 preguntas."},{"id":"w12","week":12,"title":"Derecho administrativo y función pública","focus":["derecho","pgn"],"goal":"Comprender principios administrativos, competencia, debido proceso y contexto PGN.","activities":["Finalizar Derecho.","Estudiar CPACA artículo 3.","Completar mapa mental PGN.","Resolver 35 preguntas situacionales."],"target":"≥80 % en derecho administrativo/PGN.","exam":"Caso largo jurídico-institucional."},{"id":"w13","week":13,"title":"Contratación estatal","focus":["contratacion"],"goal":"Dominar planeación, estudios previos, modalidades, riesgos y supervisión.","activities":["Completar 5 lecciones de Contratación.","Estudiar Ley 80 art. 23, Ley 1150 art. 2 y Decreto 1082 estudios previos.","Resolver 45 preguntas.","Construir flujo de contratación de una solución analítica."],"target":"≥82 % en contratación.","exam":"Caso largo de contratación tecnológica."},{"id":"w14","week":14,"title":"PGN 217 y competencias comportamentales","focus":["pgn","comportamental"],"goal":"Integrar rol, funciones, alta dirección y comportamiento esperado.","activities":["Completar PGN y Comportamental.","Resolver 40 preguntas situacionales.","Practicar decisiones bajo presión.","Revisar funciones del empleo 217."],"target":"≥85 % en PGN y ≥85 % comportamental.","exam":"Simulacro de 80 preguntas."},{"id":"w15","week":15,"title":"Integración total y corrección de debilidades","focus":["estadistica","ciencia-datos","ingenieria-datos","bases-sistemas","gobierno-datos","derecho","contratacion","pgn","comportamental"],"goal":"Eliminar temas por debajo de 75 % y estabilizar precisión.","activities":["Revisar dashboard de dominio.","Atacar 3 microcompetencias más débiles.","Resolver 100 preguntas en 2 sesiones.","Repasar flashcards vencidas y errores de alta confianza."],"target":"Ningún dominio <75 %; promedio ≥83 %.","exam":"Simulacro de 100 preguntas."},{"id":"w16","week":16,"title":"Semana de desempeño","focus":["estadistica","ciencia-datos","ingenieria-datos","bases-sistemas","gobierno-datos","derecho","contratacion","pgn","comportamental"],"goal":"Consolidar rendimiento bajo tiempo y presión.","activities":["Realizar 3 simulacros separados.","Revisar únicamente errores y fichas de alto valor.","No introducir temas grandes nuevos.","Dormir y entrenar condiciones de examen."],"target":"3 simulacros consecutivos ≥85 % y sin dominio crítico.","exam":"3 simulacros finales de 100–120 preguntas."}],"mindMaps":[{"id":"estadistica","title":"Estadística","branches":[{"label":"Variables","children":[{"label":"Escala nominal","hint":"Clasifica categorías sin orden intrínseco."},{"label":"Escala ordinal","hint":"Clasifica categorías con un orden, pero sin garantizar distancias iguales."}]},{"label":"Descriptiva","children":[{"label":"Mediana","hint":"Valor central al ordenar observaciones; es robusta frente a valores extremos."},{"label":"Desviación estándar","hint":"Mide la dispersión de los valores alrededor de la media en las mismas unidades de la variable."},{"label":"Percentil","hint":"Indica el valor por debajo del cual cae un porcentaje dado de observaciones."}]},{"label":"Probabilidad","children":[{"label":"Probabilidad condicional","hint":"Probabilidad de un evento dado que ya ocurrió otro evento."}]},{"label":"Muestreo","children":[{"label":"Sesgo de selección","hint":"Distorsión producida cuando la muestra no representa adecuadamente la población objetivo."}]},{"label":"Inferencia","children":[{"label":"Intervalo de confianza","hint":"Rango construido por un procedimiento estadístico para expresar incertidumbre sobre una estimación."},{"label":"Hipótesis nula","hint":"Proposición de referencia que una prueba estadística contrasta con los datos."},{"label":"p-value","hint":"Probabilidad, bajo H0 y el modelo asumido, de observar un resultado al menos tan extremo como el obtenido."},{"label":"Error tipo I","hint":"Rechazar H0 cuando H0 es verdadera."},{"label":"Tamaño del efecto","hint":"Cuantifica la magnitud práctica de una diferencia o relación."}]},{"label":"Relaciones","children":[{"label":"Correlación","hint":"Resume la intensidad y dirección de una asociación entre variables bajo una medida específica."}]},{"label":"Modelado","children":[{"label":"Regresión","hint":"Modela una variable objetivo en función de una o más variables explicativas."}]},{"label":"Calidad estadística","children":[{"label":"Datos faltantes","hint":"Ausencia de valores cuya causa puede afectar estimaciones y modelos."}]}]},{"id":"ciencia-datos","title":"Ciencia de datos","branches":[{"label":"Paradigmas","children":[{"label":"Aprendizaje supervisado","hint":"Aprende una relación usando ejemplos con variable objetivo conocida."}]},{"label":"Modelos","children":[{"label":"Clasificación","hint":"Predice una categoría o clase."},{"label":"Regresión predictiva","hint":"Predice un valor numérico continuo."},{"label":"Clustering","hint":"Agrupa observaciones por similitud sin usar etiquetas objetivo."}]},{"label":"Validación","children":[{"label":"Conjunto de prueba","hint":"Datos reservados para estimar desempeño sobre casos no usados en el ajuste."},{"label":"Validación cruzada","hint":"Evalúa el modelo sobre múltiples particiones para estimar estabilidad."}]},{"label":"Generalización","children":[{"label":"Overfitting","hint":"El modelo aprende demasiado el entrenamiento y pierde capacidad de generalizar."},{"label":"Underfitting","hint":"El modelo es demasiado simple o insuficientemente entrenado para capturar la señal."}]},{"label":"Calidad ML","children":[{"label":"Data leakage","hint":"Información no disponible al momento real de predicción contamina entrenamiento o evaluación."}]},{"label":"Métricas","children":[{"label":"Precision","hint":"Proporción de predicciones positivas que realmente son positivas."},{"label":"Recall","hint":"Proporción de positivos reales que el modelo logra detectar."},{"label":"F1-score","hint":"Media armónica de precision y recall."},{"label":"ROC-AUC","hint":"Mide capacidad de ranking entre clases a través de distintos umbrales."}]},{"label":"Representación","children":[{"label":"Feature engineering","hint":"Transforma o crea variables para representar mejor el fenómeno."}]},{"label":"Producción","children":[{"label":"Drift","hint":"Cambio en distribución de datos o relación con el objetivo después del despliegue."}]}]},{"id":"ingenieria-datos","title":"Ingeniería de datos","branches":[{"label":"Integración","children":[{"label":"ETL","hint":"Extraer, transformar y luego cargar datos al destino."},{"label":"ELT","hint":"Extraer y cargar datos primero, transformándolos en el motor de destino."},{"label":"Pipeline de datos","hint":"Secuencia automatizada de tareas para mover, validar y transformar datos."}]},{"label":"Confiabilidad","children":[{"label":"Idempotencia","hint":"Propiedad por la que repetir una operación produce el mismo estado esperado sin duplicar efectos."}]},{"label":"Procesamiento","children":[{"label":"Procesamiento batch","hint":"Procesa conjuntos acumulados en intervalos definidos."},{"label":"Procesamiento streaming","hint":"Procesa eventos de forma continua o con baja latencia."}]},{"label":"Arquitectura","children":[{"label":"Data warehouse","hint":"Repositorio estructurado optimizado para análisis consistente e histórico."},{"label":"Data lake","hint":"Repositorio de datos en diversos formatos y niveles de preparación."},{"label":"Data mart","hint":"Subconjunto orientado a un área o proceso específico."}]},{"label":"Modelado","children":[{"label":"Modelo estrella","hint":"Modelo dimensional con hechos centrales relacionados con dimensiones descriptivas."},{"label":"Grano de hecho","hint":"Nivel exacto que representa cada fila de una tabla de hechos."},{"label":"Slowly Changing Dimension","hint":"Técnica para gestionar cambios históricos en atributos dimensionales."}]},{"label":"Gobierno técnico","children":[{"label":"Metadatos","hint":"Datos que describen significado, estructura, origen, responsable y uso de otros datos."},{"label":"Linaje de datos","hint":"Trazabilidad del origen y transformaciones de un dato hasta su consumo."}]},{"label":"Calidad","children":[{"label":"Reglas de calidad","hint":"Controles medibles sobre completitud, validez, consistencia, unicidad u oportunidad."}]}]},{"id":"bases-sistemas","title":"Bases de datos y sistemas","branches":[{"label":"Modelo relacional","children":[{"label":"Clave primaria","hint":"Atributo o conjunto que identifica de forma única cada fila."},{"label":"Clave foránea","hint":"Restricción que relaciona filas y protege integridad referencial."},{"label":"Normalización","hint":"Organiza datos para reducir redundancia y anomalías según dependencias."}]},{"label":"SQL","children":[{"label":"JOIN","hint":"Combina filas de relaciones usando condiciones de correspondencia."},{"label":"GROUP BY y HAVING","hint":"Agrupa filas para calcular agregados; HAVING filtra grupos resultantes."},{"label":"CTE","hint":"Expresión común que nombra temporalmente un resultado para estructurar una consulta."},{"label":"Función de ventana","hint":"Calcula resultados sobre un conjunto relacionado sin colapsar filas como GROUP BY."}]},{"label":"Rendimiento","children":[{"label":"Índice","hint":"Estructura auxiliar que acelera ciertos accesos a costa de almacenamiento y escritura."}]},{"label":"Consistencia","children":[{"label":"Transacción","hint":"Unidad lógica de trabajo que se confirma o revierte como conjunto."},{"label":"ACID","hint":"Atomicidad, consistencia, aislamiento y durabilidad describen garantías transaccionales."}]},{"label":"Concurrencia","children":[{"label":"Nivel de aislamiento","hint":"Controla qué interferencias entre transacciones concurrentes se permiten."}]},{"label":"Ingeniería de software","children":[{"label":"Requisito funcional","hint":"Describe qué comportamiento o servicio debe ofrecer el sistema."},{"label":"Requisito no funcional","hint":"Describe atributos de calidad o restricciones como seguridad, disponibilidad y rendimiento."}]},{"label":"Calidad","children":[{"label":"Pruebas de integración","hint":"Verifican interacción entre componentes o servicios."}]},{"label":"Operación","children":[{"label":"Rollback y observabilidad","hint":"Rollback revierte un despliegue; observabilidad permite entender el estado mediante logs, métricas y trazas."}]}]},{"id":"gobierno-datos","title":"Gobierno de datos","branches":[{"label":"Gobierno","children":[{"label":"Data Owner","hint":"Rol responsable por decisiones y responsabilidad de negocio sobre un dominio o activo de datos."},{"label":"Data Steward","hint":"Rol que impulsa definiciones, calidad, metadatos y reglas operativas de datos."},{"label":"Custodio técnico","hint":"Rol encargado de controles técnicos de almacenamiento, disponibilidad y protección."}]},{"label":"Metadatos","children":[{"label":"Catálogo de datos","hint":"Inventario navegable de activos con definiciones, propietarios, linaje y contexto."}]},{"label":"Calidad","children":[{"label":"Completitud","hint":"Grado en que los valores requeridos están presentes."},{"label":"Consistencia","hint":"Grado en que datos relacionados no se contradicen entre sí o entre fuentes."}]},{"label":"Intercambio","children":[{"label":"Interoperabilidad","hint":"Capacidad de sistemas y organizaciones para intercambiar y usar información con significado compartido."}]},{"label":"Datos abiertos","children":[{"label":"Dato abierto","hint":"Dato público dispuesto para uso y reutilización, sujeto al marco aplicable y condiciones de calidad/publicación."}]},{"label":"Transparencia","children":[{"label":"Máxima publicidad","hint":"Principio según el cual la información bajo control de sujetos obligados se presume pública salvo excepción constitucional o legal."},{"label":"Información clasificada","hint":"Información pública cuyo acceso puede exceptuarse por afectar derechos particulares o privados en los términos legales."},{"label":"Información reservada","hint":"Información exceptuada de acceso por protección de intereses públicos bajo requisitos legales."},{"label":"Divulgación proactiva","hint":"Deber de publicar rutinariamente información de interés público, no solo responder solicitudes."}]},{"label":"Datos personales","children":[{"label":"Principio de finalidad","hint":"El tratamiento de datos debe obedecer a una finalidad legítima informada al titular cuando corresponda."},{"label":"Circulación restringida","hint":"El tratamiento y circulación de datos personales debe respetar límites y autorizaciones aplicables."}]},{"label":"Privacidad","children":[{"label":"Anonimización","hint":"Transformación orientada a reducir razonablemente la posibilidad de identificar personas en un conjunto."}]}]},{"id":"derecho","title":"Derecho","branches":[{"label":"Derecho administrativo","children":[{"label":"Principio de legalidad","hint":"La actuación administrativa debe sujetarse a la Constitución, la ley y competencias atribuidas."},{"label":"Competencia administrativa","hint":"Atribución jurídica que habilita a una autoridad para actuar sobre determinada materia."},{"label":"Debido proceso administrativo","hint":"Garantía de actuación con reglas, oportunidad de defensa y decisiones conforme al procedimiento aplicable."},{"label":"Motivación","hint":"Exposición de fundamentos fácticos y jurídicos que sostienen una decisión cuando es exigible."},{"label":"Principio de eficacia","hint":"Orienta la actuación a lograr la finalidad y efectividad de derechos evitando formalismos innecesarios."},{"label":"Principio de celeridad","hint":"Exige impulso oportuno y diligente de actuaciones administrativas."}]},{"label":"Transparencia","children":[{"label":"Acceso a información pública","hint":"Derecho de solicitar y recibir información pública de sujetos obligados bajo reglas y excepciones legales."},{"label":"Versión pública","hint":"Documento que divulga las partes accesibles y protege únicamente la información legalmente exceptuada."}]},{"label":"Datos personales","children":[{"label":"Habeas data","hint":"Facultad del titular de conocer, actualizar y rectificar información personal y garantías asociadas al tratamiento."},{"label":"Responsable del tratamiento","hint":"Quien decide sobre la base de datos o el tratamiento y sus finalidades/medios esenciales."},{"label":"Encargado del tratamiento","hint":"Quien realiza tratamiento por cuenta del responsable."},{"label":"Consentimiento informado","hint":"Autorización previa, expresa e informada cuando el tratamiento la requiere y no aplica una excepción legal."}]},{"label":"Derecho informático","children":[{"label":"Documento electrónico","hint":"Información generada, enviada, recibida o almacenada por medios electrónicos que puede tener efectos jurídicos bajo condiciones aplicables."}]},{"label":"Principios","children":[{"label":"Proporcionalidad","hint":"Exige que una medida restrictiva sea adecuada, necesaria y equilibrada respecto del fin legítimo."}]},{"label":"Gobernanza jurídica","children":[{"label":"Trazabilidad de decisión","hint":"Capacidad de reconstruir quién decidió, con qué evidencia, norma y versión de información."}]}]},{"id":"contratacion","title":"Contratación estatal","branches":[{"label":"Planeación contractual","children":[{"label":"Principio de planeación","hint":"La contratación debe partir de una necesidad definida y análisis suficiente para estructurar el proceso."},{"label":"Estudios previos","hint":"Documento de soporte que justifica necesidad y condiciones técnicas, económicas y jurídicas del proceso."},{"label":"Análisis del sector","hint":"Estudio del mercado y contexto para entender oferta, precios, riesgos y condiciones del bien o servicio."},{"label":"Plan Anual de Adquisiciones","hint":"Instrumento de planeación y publicidad de necesidades de bienes, obras y servicios proyectados."}]},{"label":"Selección","children":[{"label":"Selección objetiva","hint":"Elección basada en factores y reglas previamente definidos, evitando preferencias subjetivas."}]},{"label":"Modalidades","children":[{"label":"Licitación pública","hint":"Modalidad que opera como regla general salvo que exista causal para otra modalidad."},{"label":"Selección abreviada","hint":"Modalidad prevista para causales en las que las características del objeto o circunstancias permiten procesos simplificados."},{"label":"Concurso de méritos","hint":"Modalidad orientada a selección de consultores/proyectos en los eventos definidos por la regulación."},{"label":"Contratación directa","hint":"Modalidad excepcional aplicable únicamente bajo causales legalmente previstas."},{"label":"Mínima cuantía","hint":"Procedimiento aplicable cuando el valor no excede el umbral legal correspondiente, independientemente del objeto bajo sus reglas."}]},{"label":"Riesgos","children":[{"label":"Matriz de riesgos","hint":"Identifica, asigna y trata eventos que pueden afectar el proceso y ejecución contractual."}]},{"label":"Ejecución","children":[{"label":"Supervisión","hint":"Seguimiento técnico, administrativo, financiero, contable y jurídico que realiza la entidad cuando no requiere interventoría externa según el caso."},{"label":"Interventoría","hint":"Seguimiento especializado contratado cuando la ley o naturaleza del contrato lo requiere, con alcance definido."},{"label":"Modificación contractual","hint":"Cambio jurídicamente sustentado que debe respetar límites, finalidad, competencia y justificación."}]},{"label":"Cierre","children":[{"label":"Liquidación","hint":"Etapa o acto mediante el cual se realiza balance final de obligaciones cuando corresponde."}]}]},{"id":"pgn","title":"PGN / 217","branches":[{"label":"Naturaleza institucional","children":[{"label":"Ministerio Público","hint":"Función constitucional ejercida por órganos como la Procuraduría, Defensoría y personerías dentro de sus competencias."},{"label":"Autonomía de la PGN","hint":"La PGN tiene autonomía administrativa, financiera y presupuestal en los términos aplicables."}]},{"label":"Funciones misionales","children":[{"label":"Función preventiva","hint":"Busca prevenir irregularidades vigilando la actuación pública y advirtiendo riesgos sin coadministrar."},{"label":"Función de intervención","hint":"Intervención de la PGN como sujeto procesal ante jurisdicciones y autoridades en los casos establecidos."},{"label":"Función disciplinaria","hint":"Comprende iniciar, adelantar y fallar investigaciones disciplinarias dentro del marco aplicable."}]},{"label":"Organización","children":[{"label":"Estructura orgánica","hint":"Distribución formal de dependencias y niveles para ejercer funciones institucionales."}]},{"label":"Convocatoria 217","children":[{"label":"Dirección de Apoyo Estratégico, Análisis de Datos e Información","hint":"Dependencia asociada al empleo 217-2026 y al uso estratégico de información y analítica."},{"label":"Propósito del empleo 217","hint":"Apoyar profesionalmente innovación y desarrollo tecnológico en ciencias de datos, tecnologías emergentes y análisis de información para decisiones."},{"label":"Analítica e inteligencia de negocios","hint":"La convocatoria incluye diseño, desarrollo, pruebas y puesta en producción de soluciones de analítica y BI."},{"label":"Investigación tecnológica","hint":"Exploración y evaluación de herramientas, métodos o tecnologías para resolver necesidades institucionales."},{"label":"Instrumentos metodológicos","hint":"Métodos, lineamientos y artefactos que permiten hacer reproducible y defendible el trabajo técnico."}]},{"label":"Conocimientos esenciales","children":[{"label":"Bases de datos y sistemas de información en la 217","hint":"La convocatoria exige comprender manejo de bases de datos y sistemas de información."},{"label":"Gobierno, transparencia y datos abiertos en la 217","hint":"La convocatoria incorpora gobierno de transparencia y datos abiertos como conocimiento esencial."},{"label":"Contratación estatal en la 217","hint":"La convocatoria incluye contratación estatal dentro del conocimiento requerido."}]},{"label":"Valor del cargo","children":[{"label":"Decisión basada en información","hint":"Uso de evidencia de calidad para apoyar decisiones sin reemplazar juicio, competencia ni responsabilidad de la alta dirección."}]}]},{"id":"comportamental","title":"Comportamental","branches":[{"label":"Competencias","children":[{"label":"Responsabilidad con la organización","hint":"Actuar protegiendo objetivos, recursos, normas y confianza institucional."},{"label":"Organización del trabajo","hint":"Planificar, priorizar y controlar actividades para cumplir con calidad y plazo."},{"label":"Investigación","hint":"Buscar, contrastar y analizar información antes de concluir."},{"label":"Pensamiento conceptual","hint":"Identificar patrones, principios y relaciones para comprender problemas complejos."},{"label":"Orientación a resultados","hint":"Dirigir esfuerzos a resultados verificables sin sacrificar integridad ni calidad."},{"label":"Cumplimiento de parámetros","hint":"Trabajar dentro de estándares, procedimientos y criterios definidos."}]},{"label":"Gestión","children":[{"label":"Priorización por riesgo","hint":"Asignar atención considerando impacto y probabilidad, no solo orden de llegada."},{"label":"Comunicación de riesgos","hint":"Informar oportunamente incertidumbres, restricciones y posibles impactos a quienes deciden."},{"label":"Trazabilidad","hint":"Dejar evidencia suficiente de decisiones, cambios y responsables."},{"label":"Calidad bajo presión","hint":"Mantener controles esenciales cuando el tiempo es limitado."},{"label":"Escalamiento adecuado","hint":"Elevar un asunto cuando excede autoridad, riesgo aceptable o capacidad de resolución."},{"label":"Trabajo colaborativo","hint":"Coordinar conocimiento y responsabilidades entre perfiles para lograr un resultado común."},{"label":"Decisión basada en evidencia","hint":"Preferir información verificable y criterios explícitos frente a intuición no contrastada."},{"label":"Mejora continua","hint":"Aprender de resultados y ajustar procesos mediante evidencia."}]},{"label":"Ética","children":[{"label":"Uso ético de datos","hint":"Considerar derechos, finalidad, sesgos, seguridad y consecuencias de análisis o automatización."}]}]}],"caseStudies":[{"id":"case-stat-1","domain":"estadistica","title":"Tiempos de trámite con valores extremos","context":"La Dirección analiza 4.800 trámites. El promedio de tiempo es 18 días, la mediana 11 y el P90 41. Un grupo pequeño supera 100 días. La alta dirección pide un indicador único para comunicar el desempeño y una recomendación para investigar la cola.","questionIds":["q-estadistica-03-4","q-estadistica-05-3","q-estadistica-04-4"]},{"id":"case-stat-2","domain":"estadistica","title":"Muestra voluntaria y decisión nacional","context":"Una encuesta sobre calidad de información fue respondida voluntariamente por 42 de 120 dependencias. Las más digitalizadas respondieron en mayor proporción. El equipo desea extrapolar el resultado al total y afirmar que la calidad nacional es alta.","questionIds":["q-estadistica-07-4","q-estadistica-08-3","q-estadistica-12-4"]},{"id":"case-ds-1","domain":"ciencia-datos","title":"Modelo para priorizar casos críticos","context":"Se entrena un clasificador para priorizar revisión. Solo 4 % de casos históricos son críticos. El modelo obtiene 96 % de accuracy, pero identifica apenas 35 % de los críticos reales. Omitir un crítico tiene alto costo institucional.","questionIds":["q-ciencia-datos-10-4","q-ciencia-datos-11-4","q-ciencia-datos-12-3"]},{"id":"case-ds-2","domain":"ciencia-datos","title":"Modelo excelente que falla en producción","context":"Un modelo obtuvo 94 % de F1 durante desarrollo. Tres meses después el desempeño cae abruptamente. El equipo descubre que una variable usada durante entrenamiento contenía información registrada después del cierre del caso y que además cambió la distribución de fuentes de entrada.","questionIds":["q-ciencia-datos-09-4","q-ciencia-datos-15-4","q-ciencia-datos-05-3"]},{"id":"case-de-1","domain":"ingenieria-datos","title":"Carga nocturna duplicada","context":"Un pipeline consolida cada noche registros de cinco sistemas. Una caída ocurre después de insertar 70 % de los datos. Al reintentar el job, aparecen duplicados y el dashboard incrementa artificialmente los totales.","questionIds":["q-ingenieria-datos-04-4","q-ingenieria-datos-03-4","q-ingenieria-datos-15-3"]},{"id":"case-de-2","domain":"ingenieria-datos","title":"Plataforma analítica institucional","context":"La entidad necesita conservar archivos crudos, construir indicadores históricos consistentes y ofrecer modelos especializados por dirección. Existen datos tabulares, documentos y eventos.","questionIds":["q-ingenieria-datos-07-3","q-ingenieria-datos-08-3","q-ingenieria-datos-09-4"]},{"id":"case-db-1","domain":"bases-sistemas","title":"Reporte con dobles conteos","context":"Un reporte une trámites, actuaciones y responsables. Un trámite puede tener varias actuaciones y varios responsables. Después del JOIN, el total de trámites se duplica y los indicadores dejan de coincidir con la fuente.","questionIds":["q-bases-sistemas-04-4","q-bases-sistemas-05-3","q-bases-sistemas-07-4"]},{"id":"case-db-2","domain":"bases-sistemas","title":"Despliegue con degradación","context":"Una nueva versión modifica consultas y reglas. Después del despliegue, la latencia se triplica y aparecen errores intermitentes. No se definió rollback formal ni métricas de salud.","questionIds":["q-bases-sistemas-15-4","q-bases-sistemas-14-4","q-bases-sistemas-08-3"]},{"id":"case-gov-1","domain":"gobierno-datos","title":"Publicación de un dataset institucional","context":"Se propone publicar un dataset de actuaciones con nombres, identificadores, territorio y variables detalladas. El equipo argumenta que 'todo dato del Estado debe ser abierto'.","questionIds":["q-gobierno-datos-08-4","q-gobierno-datos-14-4","q-gobierno-datos-15-4"]},{"id":"case-gov-2","domain":"gobierno-datos","title":"Indicador con tres definiciones","context":"Tres áreas calculan el mismo indicador con reglas diferentes. No existe propietario formal, el catálogo está desactualizado y el dashboard corporativo mezcla resultados.","questionIds":["q-gobierno-datos-01-4","q-gobierno-datos-02-4","q-gobierno-datos-04-4"]},{"id":"case-law-1","domain":"derecho","title":"Solicitud de información con datos protegidos","context":"Un ciudadano solicita un informe institucional. El documento contiene análisis público y anexos con datos personales. Un área propone negar el documento completo para evitar riesgo.","questionIds":["q-derecho-07-4","q-derecho-08-4","q-derecho-09-3"]},{"id":"case-law-2","domain":"derecho","title":"Reutilización de datos para nueva finalidad","context":"Una base recolectada para un trámite se quiere reutilizar para construir un perfil automatizado no contemplado al momento de recolección. El equipo técnico puede hacerlo sin dificultad.","questionIds":["q-derecho-10-4","q-derecho-11-4","q-derecho-14-4"]},{"id":"case-contract-1","domain":"contratacion","title":"Contratación de plataforma de analítica","context":"Una dependencia solicita contratar rápidamente una plataforma sin haber definido fuentes, usuarios, requisitos de seguridad, presupuesto estimado ni riesgos. Se sugiere iniciar el proceso y 'ajustar después'.","questionIds":["q-contratacion-01-4","q-contratacion-02-4","q-contratacion-03-4"]},{"id":"case-contract-2","domain":"contratacion","title":"Cambio de alcance en ejecución","context":"Durante un contrato de software, el área usuaria solicita incluir nuevas funcionalidades que duplican esfuerzo y cambian parcialmente el propósito inicial. Se propone aprobarlas verbalmente para no retrasar.","questionIds":["q-contratacion-14-4","q-contratacion-12-4","q-contratacion-11-3"]},{"id":"case-pgn-1","domain":"pgn","title":"Analítica para alta dirección","context":"La Dirección recibe cinco fuentes con calidad desigual y necesita un tablero para priorizar riesgos institucionales. La alta dirección quiere resultados rápidos, pero el equipo aún no ha documentado definiciones ni limitaciones.","questionIds":["q-pgn-07-4","q-pgn-09-4","q-pgn-15-4"]},{"id":"case-pgn-2","domain":"pgn","title":"Alerta analítica y función institucional","context":"Un modelo identifica patrones que podrían sugerir riesgo disciplinario. Un analista propone etiquetar automáticamente a personas como responsables y publicar la lista para intervención inmediata.","questionIds":["q-pgn-05-4","q-pgn-13-4","q-pgn-15-4"]},{"id":"case-beh-1","domain":"comportamental","title":"Informe urgente con datos incompletos","context":"La alta dirección solicita un informe para el mismo día. Dos fuentes presentan inconsistencias y un compañero sugiere omitir la advertencia para no retrasar la entrega.","questionIds":["q-comportamental-08-4","q-comportamental-10-4","q-comportamental-01-4"]},{"id":"case-beh-2","domain":"comportamental","title":"Incidente de acceso a datos","context":"Detectas evidencia de acceso posiblemente indebido a información sensible. No tienes certeza del alcance y el responsable directo no está disponible.","questionIds":["q-comportamental-11-4","q-comportamental-09-3","q-comportamental-14-4"]}],"advancedChallenges":[{"id":"ch-s-01","kind":"Estadística","title":"Media vs. mediana","prompt":"Tiempos (días): 8, 9, 10, 11, 62. ¿Cuál medida representa mejor el valor típico ante el outlier?","options":["Media = 20","Mediana = 10","Rango = 54","Desviación = 0"],"answer":1,"explanation":"La mediana es 10 y es más robusta al valor extremo 62."},{"id":"ch-s-02","kind":"Estadística","title":"Media aritmética","prompt":"Valores: 12, 15, 18, 15. ¿Cuál es la media?","options":["14","15","16","60"],"answer":1,"explanation":"(12+15+18+15)/4 = 60/4 = 15."},{"id":"ch-s-03","kind":"Estadística","title":"Probabilidad condicional","prompt":"De 40 registros de la fuente A, 12 tienen error. ¿P(error | fuente A)?","options":["12 %","20 %","30 %","40 %"],"answer":2,"explanation":"12/40 = 0,30 = 30 %."},{"id":"ch-s-04","kind":"Estadística","title":"Recall","prompt":"Hay 50 casos críticos reales y el modelo detecta 40. ¿Cuál es el recall?","options":["40 %","50 %","80 %","90 %"],"answer":2,"explanation":"Recall = TP/(TP+FN)=40/50=80 %."},{"id":"ch-s-05","kind":"Estadística","title":"Precision","prompt":"El modelo marca 60 casos como críticos; 45 realmente lo son. ¿Precision?","options":["45 %","60 %","75 %","80 %"],"answer":2,"explanation":"Precision = 45/60 = 75 %."},{"id":"ch-s-06","kind":"Estadística","title":"Error absoluto","prompt":"Valor real 120, predicción 108. ¿Error absoluto?","options":["10","12","18","228"],"answer":1,"explanation":"|120-108| = 12."},{"id":"ch-s-07","kind":"Estadística","title":"Percentil","prompt":"Si P90 de tiempo es 30 días, ¿qué interpretación es correcta?","options":["90 % tarda exactamente 30","Aproximadamente 90 % está en o por debajo de 30","30 % tarda más de 90","La media es 30"],"answer":1,"explanation":"P90 es el valor bajo el cual se ubica aproximadamente el 90 % de observaciones."},{"id":"ch-s-08","kind":"Estadística","title":"Matriz de confusión","prompt":"TP=30, FP=10, FN=20, TN=40. ¿Accuracy?","options":["50 %","60 %","70 %","75 %"],"answer":2,"explanation":"Accuracy=(TP+TN)/total=(30+40)/100=70 %."},{"id":"ch-s-09","kind":"Estadística","title":"F1 simple","prompt":"Si precision=0,80 y recall=0,80, ¿F1?","options":["0,40","0,64","0,80","1,60"],"answer":2,"explanation":"Cuando precision y recall son iguales, la media armónica coincide: F1=0,80."},{"id":"ch-s-10","kind":"Estadística","title":"Cambio porcentual","prompt":"Un indicador pasa de 200 a 250. ¿Incremento porcentual?","options":["20 %","25 %","50 %","125 %"],"answer":1,"explanation":"(250-200)/200 = 25 %."},{"id":"ch-s-11","kind":"Estadística","title":"Tasa de error","prompt":"18 registros inválidos de 600. ¿Tasa de error?","options":["0,3 %","3 %","18 %","30 %"],"answer":1,"explanation":"18/600=0,03=3 %."},{"id":"ch-s-12","kind":"Estadística","title":"Promedio ponderado","prompt":"Grupo A: 80 puntos (25 % del peso); Grupo B: 90 (75 %). Resultado ponderado:","options":["82,5","85","87,5","90"],"answer":2,"explanation":"80×0,25 + 90×0,75 = 20 + 67,5 = 87,5."},{"id":"ch-q-01","kind":"SQL","title":"INNER JOIN","prompt":"¿Qué devuelve INNER JOIN entre A y B?","code":"SELECT * FROM A INNER JOIN B ON A.id=B.id;","options":["Todas las filas de A","Todas las filas de B","Solo coincidencias","Producto cartesiano"],"answer":2,"explanation":"INNER JOIN conserva filas que cumplen la condición de unión."},{"id":"ch-q-02","kind":"SQL","title":"LEFT JOIN","prompt":"Quieres conservar todos los trámites aunque no tengan actuación. ¿Qué JOIN?","options":["INNER JOIN","LEFT JOIN desde trámites","CROSS JOIN","FULL JOIN obligatorio"],"answer":1,"explanation":"LEFT JOIN conserva todas las filas de la tabla izquierda."},{"id":"ch-q-03","kind":"SQL","title":"HAVING","prompt":"¿Qué cláusula filtra grupos después de COUNT(*)?","options":["WHERE","HAVING","ORDER BY","ON"],"answer":1,"explanation":"HAVING filtra resultados agregados."},{"id":"ch-q-04","kind":"SQL","title":"COUNT DISTINCT","prompt":"Tras un JOIN 1:N quieres contar trámites únicos. ¿Qué expresión ayuda?","code":"SELECT ___(tramite_id) FROM ...","options":["COUNT(*)","COUNT(DISTINCT tramite_id)","SUM(tramite_id)","AVG(tramite_id)"],"answer":1,"explanation":"COUNT(DISTINCT ...) evita contar múltiples filas del mismo trámite."},{"id":"ch-q-05","kind":"SQL","title":"ROW_NUMBER","prompt":"¿Qué función permite numerar filas dentro de cada dependencia?","options":["COUNT","ROW_NUMBER() OVER(PARTITION BY ...)","MAX solamente","GROUP BY sin ventana"],"answer":1,"explanation":"ROW_NUMBER es una función de ventana que numera sin colapsar el detalle."},{"id":"ch-q-06","kind":"SQL","title":"Transacción","prompt":"Dos inserts dependientes deben confirmarse juntos. ¿Qué usar?","options":["Solo índice","Transacción con COMMIT/ROLLBACK","VIEW","CTE"],"answer":1,"explanation":"La transacción preserva atomicidad del conjunto lógico de cambios."},{"id":"ch-q-07","kind":"SQL","title":"Índice","prompt":"Una búsqueda frecuente por identificador único es lenta. Primera opción a evaluar:","options":["Eliminar PK","Índice adecuado y plan de ejecución","Duplicar tabla manualmente","Usar SELECT * siempre"],"answer":1,"explanation":"Se debe revisar plan de ejecución y un índice alineado al patrón de búsqueda."},{"id":"ch-q-08","kind":"SQL","title":"WHERE vs HAVING","prompt":"Quieres excluir filas con estado='ANULADO' antes de agrupar. ¿Dónde?","options":["HAVING","WHERE","ORDER BY","WINDOW"],"answer":1,"explanation":"WHERE filtra filas antes del GROUP BY."},{"id":"ch-q-09","kind":"SQL","title":"CTE","prompt":"Principal beneficio conceptual de una CTE en una consulta compleja:","options":["Garantiza índice","Mejora estructuración y legibilidad","Evita toda subconsulta","Siempre reduce costo"],"answer":1,"explanation":"Una CTE ayuda a descomponer y nombrar etapas; no garantiza mejor rendimiento."},{"id":"ch-q-10","kind":"SQL","title":"Integridad referencial","prompt":"¿Qué evita que un trámite apunte a una dependencia inexistente?","options":["CHECK de longitud","FOREIGN KEY","ORDER BY","VIEW"],"answer":1,"explanation":"Una FK protege la referencia a una fila válida de la tabla relacionada."},{"id":"ch-d-01","kind":"Data Engineering","title":"Idempotencia","prompt":"Un job puede reintentarse tras una caída. ¿Qué propiedad evita duplicados por repetición?","options":["Streaming","Idempotencia","Normalización","Visualización"],"answer":1,"explanation":"Una operación idempotente puede repetirse sin acumular efectos duplicados."},{"id":"ch-d-02","kind":"Data Engineering","title":"Batch vs streaming","prompt":"Un reporte se actualiza una vez al día y no necesita segundos de latencia. ¿Qué enfoque es más simple?","options":["Streaming obligatorio","Batch","Blockchain","Polling cada segundo"],"answer":1,"explanation":"Batch satisface una latencia diaria con menor complejidad."},{"id":"ch-d-03","kind":"Data Engineering","title":"Warehouse","prompt":"Necesitas historia consistente y métricas corporativas integradas. ¿Arquitectura principal?","options":["Data warehouse","Carpeta local","Solo API","Cache"],"answer":0,"explanation":"El warehouse está orientado a análisis histórico consistente."},{"id":"ch-d-04","kind":"Data Engineering","title":"Data lake","prompt":"Debes conservar archivos tabulares, documentos y eventos en forma cruda para usos futuros. ¿Qué encaja mejor?","options":["Data lake","Solo data mart","Una vista SQL","Spreadsheet único"],"answer":0,"explanation":"Un lake soporta variedad de formatos, pero necesita gobierno."},{"id":"ch-d-05","kind":"Data Engineering","title":"Linaje","prompt":"Debes reconstruir cómo un KPI llegó desde una fuente hasta el dashboard. ¿Qué necesitas?","options":["Linaje de datos","Más colores","Una PK compuesta siempre","Solo backup"],"answer":0,"explanation":"El linaje registra origen, transformaciones y dependencias."},{"id":"ch-d-06","kind":"Data Engineering","title":"Grano","prompt":"Antes de modelar una tabla de hechos debes definir:","options":["Color del dashboard","Grano de cada fila","Proveedor cloud","Número de índices"],"answer":1,"explanation":"El grano define exactamente qué representa una fila."},{"id":"ch-d-07","kind":"Data Engineering","title":"Calidad","prompt":"Un campo obligatorio está vacío en 8 % de filas. ¿Dimensión de calidad afectada?","options":["Completitud","Disponibilidad física solamente","Latencia de red","Escalabilidad"],"answer":0,"explanation":"La completitud mide presencia de valores esperados."},{"id":"ch-d-08","kind":"Data Engineering","title":"SCD","prompt":"Necesitas conservar el nombre anterior y actual de una dependencia en el análisis histórico. ¿Qué concepto aplica?","options":["Slowly Changing Dimension","INNER JOIN","Hash simple","Cache TTL"],"answer":0,"explanation":"SCD gestiona cambios históricos en atributos dimensionales."}],"legislation":[{"id":"law-1712-2","sourceId":"ley1712","norm":"Ley 1712 de 2014","article":"Artículo 2","title":"Máxima publicidad","explanation":"La información en poder, control o custodia de un sujeto obligado se presume pública; las restricciones deben tener fundamento constitucional o legal.","case":"Un área quiere negar un informe por considerarlo 'interno', sin identificar una excepción legal.","question":"¿Cuál debe ser el punto de partida del análisis?","answer":"La publicidad es la regla; la restricción exige fundamento constitucional o legal."},{"id":"law-1712-3","sourceId":"ley1712","norm":"Ley 1712 de 2014","article":"Artículo 3","title":"Principios de transparencia y acceso","explanation":"El acceso se interpreta con razonabilidad y proporcionalidad y bajo principios como transparencia, facilitación, no discriminación, gratuidad, celeridad y eficacia.","case":"Se exige al ciudadano justificar por qué necesita la información antes de tramitar la solicitud.","question":"¿Qué principio resulta especialmente comprometido?","answer":"No discriminación/facilitación: no debe imponerse una causa arbitraria como requisito de acceso."},{"id":"law-1712-4","sourceId":"ley1712","norm":"Ley 1712 de 2014","article":"Artículo 4","title":"Concepto del derecho de acceso","explanation":"El acceso solo puede restringirse excepcionalmente; además existe deber de divulgación proactiva y respuesta adecuada, veraz, oportuna y accesible.","case":"Una entidad publica únicamente cuando recibe solicitudes, aunque dispone de información de alto interés público.","question":"¿Qué dimensión adicional debe considerar?","answer":"La divulgación proactiva de información pública."},{"id":"law-1581-4","sourceId":"sic-datos","norm":"Ley 1581 de 2012","article":"Artículo 4","title":"Principios del tratamiento","explanation":"El tratamiento se rige por principios como legalidad, finalidad, libertad, veracidad/calidad y transparencia, entre otros.","case":"Se pretende reutilizar datos recogidos para un trámite en un perfil no relacionado.","question":"¿Qué principio exige revisar especialmente la compatibilidad del nuevo uso?","answer":"Finalidad."},{"id":"law-1581-8","sourceId":"sic-datos","norm":"Ley 1581 de 2012","article":"Artículo 8","title":"Derechos del titular","explanation":"Incluye derechos como conocer, actualizar y rectificar datos; solicitar prueba de autorización cuando corresponda y ser informado sobre el uso.","case":"Una persona detecta un dato personal inexacto en un sistema institucional.","question":"¿Qué derecho es directamente relevante?","answer":"Actualizar y rectificar sus datos personales."},{"id":"law-1437-3","sourceId":"cpaca","norm":"Ley 1437 de 2011 (CPACA)","article":"Artículo 3","title":"Principios de las actuaciones administrativas","explanation":"Las actuaciones se orientan por principios como debido proceso, igualdad, imparcialidad, buena fe, responsabilidad, transparencia, publicidad, coordinación, eficacia, economía y celeridad.","case":"Una dependencia omite la oportunidad de contradicción para acelerar una decisión.","question":"¿Qué principio se afecta de manera directa?","answer":"Debido proceso."},{"id":"law-80-23","sourceId":"ley80","norm":"Ley 80 de 1993","article":"Artículo 23","title":"Principios de las actuaciones contractuales","explanation":"La contratación estatal se desarrolla con arreglo a transparencia, economía y responsabilidad, además de postulados de la función administrativa.","case":"Un equipo cambia criterios de evaluación después de conocer propuestas.","question":"¿Qué principio contractual se compromete claramente?","answer":"Transparencia."},{"id":"law-1150-2","sourceId":"ley1150","norm":"Ley 1150 de 2007","article":"Artículo 2","title":"Modalidades de selección","explanation":"Regula modalidades como licitación pública, selección abreviada, concurso de méritos y contratación directa; la licitación opera como regla general salvo excepciones previstas.","case":"Se busca una modalidad por ser 'más rápida' sin revisar la causal legal.","question":"¿Qué debe verificarse primero?","answer":"Que el objeto, cuantía o circunstancia encaje en la modalidad y causal legal aplicable."},{"id":"law-1082-studies","sourceId":"decreto1082","norm":"Decreto 1082 de 2015","article":"Artículo 2.2.1.1.2.1.1","title":"Estudios y documentos previos","explanation":"Los estudios previos soportan proyecto de pliegos, pliegos y contrato, e incluyen necesidad, objeto/especificaciones, modalidad y justificación, valor estimado, entre otros elementos.","case":"Se quiere iniciar una compra tecnológica sin definir necesidad ni justificar modalidad.","question":"¿Qué documento debe estructurarse antes del proceso?","answer":"Estudios y documentos previos."},{"id":"law-pgn-structure","sourceId":"decreto262","norm":"Decreto Ley 262 de 2000 y modificaciones","article":"Estructura y competencias","title":"Competencia y organización de la PGN","explanation":"La estructura y distribución de funciones determinan qué dependencia y autoridad están habilitadas para actuar.","case":"Un equipo técnico recibe una solicitud que implica una decisión reservada a otra dependencia.","question":"¿Qué debe hacerse antes de asumir la actuación?","answer":"Verificar competencia y canalizar o coordinar con la autoridad/dependencia competente."}],"domainMeta":{"estadistica":{"title":"Análisis de datos y estadística","short":"Estadística","color":"#45d2bf","description":"Descriptiva, probabilidad e inferencia para decisiones basadas en evidencia."},"ciencia-datos":{"title":"Ciencia de datos","short":"Data Science","color":"#8b7df4","description":"Modelado predictivo, validación y métricas orientadas a problemas."},"ingenieria-datos":{"title":"Ingeniería de datos","short":"Data Engineering","color":"#43a8ff","description":"Pipelines, arquitectura analítica, calidad, metadatos y trazabilidad."},"bases-sistemas":{"title":"Bases de datos y sistemas de información","short":"BD y sistemas","color":"#f5b64a","description":"SQL, transacciones, requisitos, pruebas, integración y producción."},"gobierno-datos":{"title":"Gobierno, transparencia y datos abiertos","short":"Gobierno de datos","color":"#f06e7c","description":"Gobierno, calidad, interoperabilidad, transparencia, apertura y privacidad."},"derecho":{"title":"Derecho constitucional, administrativo e informático","short":"Derecho","color":"#ef8c5c","description":"Principios jurídicos aplicables a actuación pública, información y datos personales."},"contratacion":{"title":"Contratación estatal","short":"Contratación","color":"#ffd166","description":"Planeación, selección, riesgos, ejecución, supervisión y cierre contractual."},"pgn":{"title":"Procuraduría y Convocatoria 217","short":"PGN","color":"#6ed69c","description":"Naturaleza, funciones misionales, estructura y capacidades requeridas por el empleo 217."},"comportamental":{"title":"Competencias comportamentales","short":"Comportamental","color":"#b58cff","description":"Responsabilidad, organización, investigación, pensamiento conceptual y resultados."}}};
